// Texts for the "Kimyoviy asboblar" screen (apparatus.js draws the 3D models): purpose, material, use, inventor, history, fact, safety in uz/en/ru.
window.PT_APP = [{"id":"test_tube","icon":"🧪","cat":"glass","uz":{"name":"Probirka","short":"Probirka — bir uchi yopiq, yumaloq tubli ingichka shisha naycha.","purpose":"Probirkada oz miqdordagi moddalar bilan tajribalar o'tkaziladi: eritmalar aralashtiriladi, reaksiyalar kuzatiladi va moddalar qizdiriladi. U maktab laboratoriyasidagi eng ko'p ishlatiladigan idishdir.","material":"Odatda issiqqa chidamli borosilikat shishadan yasaladi, shuning uchun alangada qizdirish va keskin harorat o'zgarishiga bardosh beradi. Shaffof shisha reaksiyani yaxshi ko'rish imkonini beradi.","use":["Probirkani hajmining uchdan biridan ko'p to'ldirmang.","Qizdirishda probirka qisqichidan foydalaning.","Avval probirkani butun uzunligi bo'yicha bir tekis isiting, keyin modda turgan joyni qizdiring.","Probirka og'zini o'zingizga va boshqalarga qaratmang.","Ishdan keyin probirkani yuvib, shtativga og'zini pastga qaratib qo'ying."],"inventor":"Noma'lum — asta-sekin rivojlangan","year":"XVIII–XIX asr","history":"Kichik shisha idishlardan alkimyogarlar ham foydalangan. Hozirgi ko'rinishdagi probirka XVIII–XIX asrlarda kimyo fan sifatida rivojlanib, kichik hajmdagi tajribalar ko'paygan davrda keng tarqaldi. Issiqqa chidamli borosilikat shisha paydo bo'lgach, probirkalarni bemalol qizdirish mumkin bo'ldi.","fact":"Probirkaning tubi yumaloq qilinadi, chunki bunday tub qizdirilganda bir tekis isiydi va yuvish oson bo'ladi.","safety":"Probirkani qizdirayotganda uning og'zini hech qachon o'zingizga yoki yoningizdagi odamga qaratmang."},"en":{"name":"Test tube","short":"A test tube is a narrow glass tube that is closed and rounded at one end.","purpose":"Test tubes are used for experiments with small amounts of substances: mixing solutions, watching reactions and heating samples. It is the most common vessel in a school laboratory.","material":"It is usually made of heat-resistant borosilicate glass, so it can be heated in a flame and survive sudden temperature changes. The clear glass lets you see the reaction well.","use":["Do not fill a test tube more than one third full.","Use a test tube holder when heating.","Warm the whole tube evenly first, then heat the part with the substance.","Never point the open end at yourself or others.","After work, wash the tube and place it upside down in the rack."],"inventor":"Unknown — developed gradually","year":"18th–19th century","history":"Small glass vessels were already used by alchemists. The test tube as we know it spread in the 18th–19th centuries, when chemistry became a science and small-scale experiments grew common. With heat-resistant borosilicate glass, test tubes could be heated safely.","fact":"The bottom of a test tube is rounded because a round bottom heats evenly and is easy to clean.","safety":"When heating a test tube, never point its mouth at yourself or anyone nearby."},"ru":{"name":"Пробирка","short":"Пробирка — узкая стеклянная трубка, закрытая и закруглённая с одного конца.","purpose":"В пробирке проводят опыты с небольшими количествами веществ: смешивают растворы, наблюдают реакции и нагревают вещества. Это самая распространённая посуда в школьной лаборатории.","material":"Обычно её делают из термостойкого боросиликатного стекла, поэтому её можно нагревать в пламени и она выдерживает резкие перепады температуры. Прозрачное стекло позволяет хорошо видеть реакцию.","use":["Не заполняйте пробирку больше чем на треть.","При нагревании держите пробирку пробиркодержателем.","Сначала равномерно прогрейте всю пробирку, затем нагревайте место с веществом.","Не направляйте отверстие пробирки на себя и других.","После работы вымойте пробирку и поставьте её в штатив отверстием вниз."],"inventor":"Неизвестен — развивалась постепенно","year":"XVIII–XIX век","history":"Небольшими стеклянными сосудами пользовались ещё алхимики. Пробирка привычного вида распространилась в XVIII–XIX веках, когда химия стала наукой и опыты с малыми количествами веществ стали обычными. С появлением термостойкого боросиликатного стекла пробирки стало можно безопасно нагревать.","fact":"Дно пробирки делают круглым, потому что такое дно равномерно прогревается и легко моется.","safety":"При нагревании никогда не направляйте отверстие пробирки на себя или на соседей."}},{"id":"test_tube_rack","icon":"🗄️","cat":"support","uz":{"name":"Probirkalar shtativi","short":"Probirkalar shtativi — probirkalarni tik holatda ushlab turadigan teshikli taglik.","purpose":"Shtativ probirkalarni ag'darilib ketmasligi uchun tik turg'izib qo'yishga xizmat qiladi. Unda bir nechta tajribani yonma-yon tayyorlash va natijalarni solishtirish qulay. Yuvilgan probirkalarni quritish uchun ham ishlatiladi.","material":"Yog'och, plastmassa yoki zanglamaydigan metalldan yasaladi. Plastmassa va metall shtativlar oson yuviladi, yog'och shtativlar esa arzon va yengil.","use":["Shtativni stolning tekis va barqaror joyiga qo'ying.","Probirkalarni teshiklarga ehtiyotkorlik bilan, qisilmasdan kiriting.","Qaynoq probirkani plastmassa shtativga qo'ymang — avval soviting.","Probirkalarni tartib bilan joylashtirib, kerak bo'lsa belgi qo'ying."],"inventor":"Noma'lum","year":"XIX asr","history":"Probirkalar keng tarqalgach, ularni xavfsiz saqlash uchun oddiy yog'och taglik va tokchalar ishlatila boshlandi. XIX asr laboratoriyalarida yog'och shtativlar odatiy jihozga aylandi. Keyinchalik plastmassa va metall shtativlar paydo bo'ldi.","fact":"Ba'zi shtativlarda probirkalarni og'zini pastga qaratib quritish uchun maxsus tayoqchalar bo'ladi.","safety":"Qizdirilgan probirkani plastmassa shtativga qo'ymang, chunki shtativ erib ketishi mumkin."},"en":{"name":"Test tube rack","short":"A test tube rack is a stand with holes that holds test tubes upright.","purpose":"The rack keeps test tubes standing so they do not tip over. It makes it easy to prepare several experiments side by side and compare the results. It is also used to dry washed tubes.","material":"It is made of wood, plastic or stainless steel. Plastic and metal racks are easy to clean, while wooden racks are cheap and light.","use":["Place the rack on a flat, stable part of the bench.","Put the tubes into the holes gently, without forcing them.","Do not put a hot tube into a plastic rack — let it cool first.","Arrange the tubes in order and label them if needed."],"inventor":"Unknown","year":"19th century","history":"Once test tubes became common, simple wooden blocks and shelves were used to hold them safely. Wooden racks were standard equipment in 19th-century laboratories. Later, plastic and metal racks appeared.","fact":"Some racks have small pegs for drying test tubes upside down.","safety":"Do not place a heated test tube in a plastic rack, because the rack can melt."},"ru":{"name":"Штатив для пробирок","short":"Штатив для пробирок — подставка с отверстиями, которая держит пробирки вертикально.","purpose":"Штатив удерживает пробирки в вертикальном положении, чтобы они не опрокидывались. В нём удобно готовить несколько опытов рядом и сравнивать результаты. Его также используют для сушки вымытых пробирок.","material":"Делается из дерева, пластмассы или нержавеющей стали. Пластмассовые и металлические штативы легко моются, а деревянные дёшевы и лёгкие.","use":["Ставьте штатив на ровное и устойчивое место стола.","Вставляйте пробирки в гнёзда аккуратно, не зажимая их.","Не ставьте горячую пробирку в пластмассовый штатив — сначала охладите её.","Расставляйте пробирки по порядку и при необходимости подписывайте их."],"inventor":"Неизвестен","year":"XIX век","history":"Когда пробирки стали широко использоваться, для их хранения начали применять простые деревянные подставки и полочки. В лабораториях XIX века деревянные штативы стали обычным оборудованием. Позже появились пластмассовые и металлические штативы.","fact":"У некоторых штативов есть штырьки для сушки пробирок отверстием вниз.","safety":"Не ставьте нагретую пробирку в пластмассовый штатив — он может расплавиться."}},{"id":"test_tube_holder","icon":"🗜️","cat":"support","uz":{"name":"Probirka qisqichi","short":"Probirka qisqichi — probirkani ushlab turish uchun mo'ljallangan qisqich.","purpose":"Qisqich qizdirilayotgan yoki issiq probirkani qo'l kuymasdan ushlashga yordam beradi. U probirkani alangadan xavfsiz masofada tutib turish imkonini beradi.","material":"Yog'och yoki sim (metall)dan yasaladi. Yog'och issiqlikni yomon o'tkazadi, shuning uchun qo'l kuymaydi; metall qisqichlar esa mustahkam va uzoq xizmat qiladi.","use":["Qisqichni probirkaning og'ziga yaqin, yuqori uchdan bir qismiga mahkamlang.","Probirkani alangaga qiya holda tuting.","Qisqichni dastasidan ushlang, probirkaga qo'l tekkizmang.","Qisqich probirkani mahkam ushlayotganini tekshirib oling."],"inventor":"Noma'lum","year":"XIX asr","history":"Issiq idishlarni ushlash uchun turli qisqich va ombirlardan qadimdan foydalanilgan. Probirkalar keng tarqalgan XIX asrda ular uchun maxsus yengil qisqichlar ishlatila boshlandi. Hozir yog'och va prujinali sim qisqichlar eng keng tarqalgan.","fact":"Yog'och qisqichlar ko'pincha prujina bilan ishlaydi: dastani qissangiz, jag'lari ochiladi.","safety":"Qisqichni alangaga juda yaqin tutmang — yog'och qisqich yonib ketishi mumkin."},"en":{"name":"Test tube holder","short":"A test tube holder is a clamp for holding a single test tube.","purpose":"The holder lets you hold a hot or heated test tube without burning your hand. It keeps the tube at a safe distance from the flame.","material":"It is made of wood or wire (metal). Wood conducts heat poorly, so your hand stays cool; metal holders are strong and last long.","use":["Clamp the holder near the top of the tube, about one third from the mouth.","Hold the tube at an angle in the flame.","Hold the holder by its handle and do not touch the tube.","Check that the holder grips the tube firmly."],"inventor":"Unknown","year":"19th century","history":"Tongs and clamps for handling hot vessels have been used for a very long time. In the 19th century, when test tubes became common, light holders made especially for them came into use. Today wooden and spring-wire holders are the most common.","fact":"Many wooden holders use a spring: squeeze the handle and the jaws open.","safety":"Do not hold a wooden holder too close to the flame, because it can catch fire."},"ru":{"name":"Пробиркодержатель","short":"Пробиркодержатель — зажим для удержания пробирки.","purpose":"Держатель позволяет держать горячую или нагреваемую пробирку, не обжигая руку. Он удерживает пробирку на безопасном расстоянии от пламени.","material":"Его делают из дерева или проволоки (металла). Дерево плохо проводит тепло, поэтому рука не обжигается; металлические держатели прочные и долговечные.","use":["Закрепляйте держатель у верхней части пробирки, примерно на трети от отверстия.","Держите пробирку в пламени наклонно.","Держите держатель за ручку и не касайтесь пробирки.","Проверьте, что держатель крепко удерживает пробирку."],"inventor":"Неизвестен","year":"XIX век","history":"Щипцы и зажимы для горячей посуды использовались очень давно. В XIX веке, когда пробирки получили широкое распространение, появились лёгкие держатели специально для них. Сегодня чаще всего применяют деревянные и пружинные проволочные держатели.","fact":"Многие деревянные держатели работают на пружине: сожмите ручку — и зажим раскроется.","safety":"Не подносите деревянный держатель слишком близко к пламени — он может загореться."}},{"id":"beaker","icon":"🥛","cat":"glass","uz":{"name":"Kimyoviy stakan (Griffin stakani)","short":"Kimyoviy stakan — tekis tubli, quyish uchun tumshuqchali silindr shaklidagi shisha idish.","purpose":"Kimyoviy stakanda eritmalar tayyorlanadi, aralashtiriladi, qizdiriladi va moddalar vaqtincha saqlanadi. Undagi chiziqlar hajmni taxminan ko'rsatadi, lekin aniq o'lchash uchun mo'ljallanmagan.","material":"Asosan issiqqa chidamli borosilikat shishadan, ba'zan plastmassadan yasaladi. Borosilikat shisha qizdirishga va harorat o'zgarishiga chidamli, kislotalar bilan deyarli reaksiyaga kirishmaydi.","use":["Stakanni plitada yoki to'r ustida qizdiring, ochiq alangaga to'g'ridan-to'g'ri qo'ymang.","Aralashtirish uchun shisha tayoqchadan foydalaning.","Suyuqlikni tumshuqcha orqali, kerak bo'lsa tayoqcha bo'ylab quying.","Aniq hajm kerak bo'lsa, o'lchov silindri yoki pipetkadan foydalaning."],"inventor":"Noma'lum; Griffin stakani Jon Jozef Griffin (Britaniya) nomi bilan ataladi","year":"XIX asr","history":"Ochiq shisha idishlar laboratoriyalarda uzoq vaqtdan beri ishlatilgan. Tumshuqchali past stakan XIX asrda laboratoriya jihozlarini ishlab chiqargan va sotgan britaniyalik kimyogar Jon Jozef Griffin nomi bilan «Griffin stakani» deb ataladi. Uni aynan kim birinchi bo'lib yasagani aniq ma'lum emas.","fact":"Kimyoviy stakandagi shkala odatda faqat taxminan 5–10% aniqlikka ega.","safety":"Issiq stakanni qo'l bilan emas, maxsus qisqich yoki issiqbardosh qo'lqop bilan ushlang."},"en":{"name":"Beaker (Griffin beaker)","short":"A beaker is a flat-bottomed cylindrical glass vessel with a small spout for pouring.","purpose":"Beakers are used to prepare, mix, heat and briefly hold solutions. Their markings show volume only roughly and are not meant for accurate measuring.","material":"Most are made of heat-resistant borosilicate glass, some of plastic. Borosilicate glass withstands heating and temperature changes and hardly reacts with acids.","use":["Heat a beaker on a hot plate or on a gauze, not directly in an open flame.","Stir with a glass rod.","Pour through the spout, along a glass rod if needed.","For exact volumes use a graduated cylinder or a pipette."],"inventor":"Unknown; the Griffin beaker is named after John Joseph Griffin (Britain)","year":"19th century","history":"Open glass vessels have long been used in laboratories. The low beaker with a spout is called the Griffin beaker after John Joseph Griffin, a 19th-century British chemist who made and sold laboratory apparatus. Exactly who made the first one is not known.","fact":"The scale on a beaker is usually accurate only to about 5–10%.","safety":"Pick up a hot beaker with beaker tongs or heat-resistant gloves, never with bare hands."},"ru":{"name":"Химический стакан (стакан Гриффина)","short":"Химический стакан — цилиндрический стеклянный сосуд с плоским дном и носиком для переливания.","purpose":"В химическом стакане готовят, смешивают и нагревают растворы, а также временно хранят вещества. Деления на нём показывают объём лишь приблизительно и не предназначены для точных измерений.","material":"Чаще всего его делают из термостойкого боросиликатного стекла, иногда из пластмассы. Боросиликатное стекло выдерживает нагревание и перепады температур и почти не реагирует с кислотами.","use":["Нагревайте стакан на плитке или на сетке, а не прямо в открытом пламени.","Перемешивайте стеклянной палочкой.","Переливайте жидкость через носик, при необходимости по палочке.","Для точного объёма используйте мерный цилиндр или пипетку."],"inventor":"Неизвестен; стакан Гриффина назван в честь Джона Джозефа Гриффина (Великобритания)","year":"XIX век","history":"Открытые стеклянные сосуды давно применяются в лабораториях. Низкий стакан с носиком называют «стаканом Гриффина» в честь британского химика XIX века Джона Джозефа Гриффина, который производил и продавал лабораторное оборудование. Кто именно сделал первый такой стакан, точно неизвестно.","fact":"Шкала на химическом стакане обычно точна лишь примерно на 5–10%.","safety":"Берите горячий стакан щипцами или термостойкими перчатками, а не голыми руками."}},{"id":"erlenmeyer","icon":"⚗️","cat":"glass","uz":{"name":"Konussimon kolba (Erlenmeyer kolbasi)","short":"Konussimon kolba — tekis tubli, konus shaklida torayib boruvchi, ingichka bo'g'izli shisha idish.","purpose":"U eritmalarni aralashtirish, qizdirish va titrlash uchun ishlatiladi. Tor bo'g'iz suyuqlikni chayqatganda to'kilishdan va bug'lanishdan saqlaydi. Uni probka bilan yopib saqlash ham qulay.","material":"Issiqqa chidamli borosilikat shishadan yasaladi, shuning uchun uni qizdirish va tez sovitish mumkin. Ba'zan plastmassa variantlari ham bo'ladi.","use":["Aralashtirish uchun kolbani bo'g'zidan ushlab, aylana harakat bilan chayqating.","Titrlashda kolba tagiga oq qog'oz qo'yib, rang o'zgarishini kuzating.","Qizdirganda to'r yoki plitadan foydalaning.","Kolbani hajmining yarmidan ortiq to'ldirmang."],"inventor":"Emil Erlenmeyer (Germaniya)","year":"1860","history":"Bu kolbani nemis kimyogari Emil Erlenmeyer 1860-yilda taklif qilgan. Uning konus shakli suyuqlikni to'kmasdan chayqatish imkonini berdi. Tez orada u butun dunyo laboratoriyalarida eng mashhur idishlardan biriga aylandi.","fact":"Erlenmeyer mashhur «Erlenmeyer qoidasi»ni ham ta'riflagan: gidroksil guruhi qo'shbog'li uglerodga birikkan spirtlar odatda beqaror bo'ladi.","safety":"Yopiq kolbani hech qachon qizdirmang — ichidagi bosim oshib, kolba yorilishi mumkin."},"en":{"name":"Erlenmeyer flask (conical flask)","short":"An Erlenmeyer flask is a flat-bottomed glass flask that narrows in a cone shape to a thin neck.","purpose":"It is used for mixing, heating and titrating solutions. The narrow neck stops liquid from splashing out when swirled and reduces evaporation. It is also easy to close with a stopper.","material":"It is made of heat-resistant borosilicate glass, so it can be heated and cooled quickly. Plastic versions also exist.","use":["To mix, hold the flask by the neck and swirl it in circles.","When titrating, put white paper under the flask to see the colour change.","Use a gauze or hot plate when heating.","Do not fill the flask more than half full."],"inventor":"Emil Erlenmeyer (Germany)","year":"1860","history":"The German chemist Emil Erlenmeyer introduced this flask in 1860. Its conical shape made it possible to swirl liquids without spilling. It soon became one of the most popular vessels in laboratories worldwide.","fact":"Erlenmeyer also described the Erlenmeyer rule: alcohols with the hydroxyl group on a double-bonded carbon are usually unstable.","safety":"Never heat a closed flask — the pressure inside can build up and crack it."},"ru":{"name":"Коническая колба (колба Эрленмейера)","short":"Коническая колба — стеклянная колба с плоским дном, конусом сужающаяся к узкому горлу.","purpose":"Её используют для смешивания, нагревания и титрования растворов. Узкое горло не даёт жидкости выплёскиваться при перемешивании и уменьшает испарение. Её также удобно закрывать пробкой.","material":"Делается из термостойкого боросиликатного стекла, поэтому её можно нагревать и быстро охлаждать. Бывают и пластмассовые варианты.","use":["Для перемешивания держите колбу за горло и вращайте круговыми движениями.","При титровании подложите под колбу белую бумагу, чтобы видеть изменение цвета.","Нагревайте на сетке или плитке.","Не заполняйте колбу больше чем наполовину."],"inventor":"Эмиль Эрленмейер (Германия)","year":"1860","history":"Эту колбу предложил немецкий химик Эмиль Эрленмейер в 1860 году. Коническая форма позволила перемешивать жидкость, не расплёскивая её. Вскоре она стала одной из самых популярных колб в лабораториях всего мира.","fact":"Эрленмейер также сформулировал «правило Эрленмейера»: спирты с гидроксильной группой у атома углерода при двойной связи обычно неустойчивы.","safety":"Никогда не нагревайте закрытую колбу — давление внутри может возрасти и разорвать её."}},{"id":"round_flask","icon":"⚗️","cat":"glass","uz":{"name":"Yumaloq tubli kolba","short":"Yumaloq tubli kolba — shar shaklidagi, uzun bo'g'izli shisha kolba.","purpose":"U suyuqliklarni bir tekis qizdirish, qaynatish va haydash (distillash) uchun ishlatiladi. Sferik shakli tufayli issiqlik va bosim butun devor bo'ylab teng taqsimlanadi. Shu sababli vakuum ostida ishlash uchun ham mos.","material":"Issiqqa chidamli borosilikat shishadan yasaladi. Bu shisha kuchli qizdirish va keskin harorat o'zgarishiga bardosh beradi.","use":["Kolba stolda turmaydi — uni shtativga qisqich bilan mahkamlang yoki maxsus halqali taglikka qo'ying.","Qaynatishda bir tekis qaynash uchun qaynash toshchalarini soling.","Kolbani hajmining yarmidan ko'p to'ldirmang.","Qizdirishni sekin, to'r yoki suv/yog' hammomida boshlang."],"inventor":"Noma'lum — alkimyogarlar idishlaridan rivojlangan","year":"Qadimgi davr (hozirgi shakli XIX asr)","history":"Yumaloq shisha idishlarni qadimgi va o'rta asr alkimyogarlari moddalarni qizdirish va haydash uchun ishlatgan. XIX asrda shisha sanoati rivojlanib, standart o'lchamdagi yumaloq kolbalar ishlab chiqarila boshlandi. Keyinchalik shlifli bo'g'izlar ularni boshqa asboblarga germetik ulash imkonini berdi.","fact":"Shar shakli idishni vakuumda yorilishdan eng yaxshi himoya qiladi, shuning uchun vakuumli haydashda yumaloq kolba ishlatiladi.","safety":"Yumaloq kolbani hech qachon tekis stolga qo'yib qoldirmang — u dumalab tushib sinishi mumkin."},"en":{"name":"Round-bottom flask","short":"A round-bottom flask is a spherical glass flask with a long neck.","purpose":"It is used for heating liquids evenly, boiling and distillation. Thanks to its spherical shape, heat and pressure spread evenly over the whole wall. That is why it is also suitable for work under vacuum.","material":"It is made of heat-resistant borosilicate glass, which withstands strong heating and sudden temperature changes.","use":["It cannot stand on the bench — clamp it to a stand or place it on a cork ring.","Add boiling chips for smooth boiling.","Do not fill it more than half full.","Start heating slowly, using a gauze or a water/oil bath."],"inventor":"Unknown — developed from alchemists' vessels","year":"Ancient times (modern form 19th century)","history":"Round glass vessels were used by ancient and medieval alchemists for heating and distilling substances. In the 19th century, as the glass industry grew, round flasks of standard sizes began to be produced. Later, ground-glass necks allowed them to be joined tightly to other apparatus.","fact":"A sphere is the best shape for resisting implosion under vacuum, which is why round flasks are used in vacuum distillation.","safety":"Never leave a round-bottom flask loose on a flat bench — it can roll off and break."},"ru":{"name":"Круглодонная колба","short":"Круглодонная колба — стеклянная колба шарообразной формы с длинным горлом.","purpose":"Её используют для равномерного нагревания жидкостей, кипячения и перегонки. Благодаря сферической форме тепло и давление распределяются по стенкам равномерно. Поэтому она подходит и для работы под вакуумом.","material":"Делается из термостойкого боросиликатного стекла, которое выдерживает сильное нагревание и резкие перепады температуры.","use":["На столе колба не стоит — закрепите её в лапке штатива или поставьте на подставку-кольцо.","Для равномерного кипения добавьте кипелки.","Не заполняйте колбу больше чем наполовину.","Начинайте нагрев медленно, на сетке или на водяной/масляной бане."],"inventor":"Неизвестен — произошла от сосудов алхимиков","year":"Древность (современный вид — XIX век)","history":"Круглые стеклянные сосуды применяли ещё древние и средневековые алхимики для нагревания и перегонки веществ. В XIX веке с развитием стекольной промышленности начали выпускать круглые колбы стандартных размеров. Позже шлифованные горла позволили герметично соединять их с другими приборами.","fact":"Шар лучше всего противостоит вакууму, поэтому для вакуумной перегонки используют круглодонные колбы.","safety":"Никогда не оставляйте круглодонную колбу просто на столе — она может скатиться и разбиться."}},{"id":"flat_flask","icon":"🫙","cat":"glass","uz":{"name":"Yassi tubli kolba (Florensiya kolbasi)","short":"Yassi tubli kolba — shar shaklidagi, lekin tubi tekis bo'lgan uzun bo'g'izli shisha kolba.","purpose":"Unda eritmalar tayyorlanadi, saqlanadi va qizdiriladi. Tekis tubi tufayli kolba stolda o'zi tik turadi. U oddiy qizdirish va qaynatish uchun qulay, ammo vakuum ostida ishlatilmaydi.","material":"Issiqqa chidamli borosilikat shishadan yasaladi, shuning uchun uni qizdirish mumkin. Shaffof shisha suyuqlik holatini kuzatishga yordam beradi.","use":["Kolbani tekis, barqaror joyga qo'ying.","Qizdirishda to'r yoki plitadan foydalaning.","Qaynatishda qaynash toshchalarini qo'shing.","Vakuum bilan ishlash uchun yassi tubli emas, yumaloq tubli kolbani tanlang."],"inventor":"Noma'lum","year":"XIX asr","history":"Yassi tubli kolbaning ixtirochisi ma'lum emas; u yumaloq kolbaning stolda turadigan qulay varianti sifatida paydo bo'lgan. Ingliz tilidagi «Florence flask» nomi Italiyaning Florensiya shahri bilan bog'liq, u yerda shunga o'xshash shisha idishlar keng tarqalgan bo'lgan. XIX asrda u laboratoriyalarning odatiy jihoziga aylandi.","fact":"Tekis tub kolbani qulay qiladi, lekin uni yumaloq kolbaga nisbatan bosim farqiga kamroq chidamli qiladi.","safety":"Yassi tubli kolbani vakuum ostida ishlatmang — tekis tub bosimga chidamay yorilishi mumkin."},"en":{"name":"Flat-bottom flask (Florence flask)","short":"A flat-bottom flask is a round-bodied glass flask with a long neck and a flat base.","purpose":"It is used to prepare, store and heat solutions. Thanks to its flat base, it stands on the bench by itself. It is handy for simple heating and boiling but is not used under vacuum.","material":"It is made of heat-resistant borosilicate glass, so it can be heated. The clear glass lets you watch the liquid.","use":["Stand the flask on a flat, stable surface.","Use a gauze or hot plate for heating.","Add boiling chips when boiling.","For vacuum work, choose a round-bottom flask instead."],"inventor":"Unknown","year":"19th century","history":"No inventor of the flat-bottom flask is known; it appeared as a version of the round flask that can stand on its own. The English name Florence flask is linked with the Italian city of Florence, where similar glass vessels were widely used. By the 19th century it was a standard piece of laboratory equipment.","fact":"The flat base makes the flask convenient, but less able to withstand pressure differences than a round flask.","safety":"Do not use a flat-bottom flask under vacuum — the flat base can crack under the pressure."},"ru":{"name":"Плоскодонная колба (флорентийская колба)","short":"Плоскодонная колба — стеклянная колба с шарообразным корпусом, длинным горлом и плоским дном.","purpose":"В ней готовят, хранят и нагревают растворы. Благодаря плоскому дну колба сама стоит на столе. Она удобна для простого нагревания и кипячения, но под вакуумом её не используют.","material":"Делается из термостойкого боросиликатного стекла, поэтому её можно нагревать. Прозрачное стекло позволяет наблюдать за жидкостью.","use":["Ставьте колбу на ровное устойчивое место.","Нагревайте на сетке или плитке.","При кипячении добавляйте кипелки.","Для работы под вакуумом выбирайте круглодонную колбу."],"inventor":"Неизвестен","year":"XIX век","history":"Изобретатель плоскодонной колбы неизвестен; она появилась как удобный вариант круглой колбы, способный стоять на столе. Английское название «Florence flask» связано с итальянским городом Флоренцией, где были распространены похожие стеклянные сосуды. К XIX веку она стала обычным лабораторным оборудованием.","fact":"Плоское дно делает колбу удобной, но хуже выдерживает перепад давления, чем круглое.","safety":"Не используйте плоскодонную колбу под вакуумом — плоское дно может треснуть."}},{"id":"wurtz_flask","icon":"⚗️","cat":"glass","uz":{"name":"Vyurts kolbasi","short":"Vyurts kolbasi — bo'g'zidan yon tomonga chiqarilgan naychasi bor yumaloq tubli kolba.","purpose":"U suyuqliklarni haydash (distillash) va gazlar olish uchun ishlatiladi. Bug' yoki gaz yon naycha orqali sovutgichga yoki yig'ish idishiga boradi. Bo'g'izga termometr o'rnatib, bug' haroratini o'lchash mumkin.","material":"Issiqqa chidamli borosilikat shishadan yasaladi, chunki haydashda kolba kuchli qizdiriladi.","use":["Kolbani shtativga qisqich bilan mahkamlang.","Yon naychani sovutgich yoki gaz o'tkazgich nayga zich ulang.","Termometr sharchasi yon naycha ro'parasida turishi kerak.","Suyuqlikni hajmining yarmidan ko'p quymang va qaynash toshchalarini qo'shing."],"inventor":"Sharl Adolf Vyurts (Fransiya) nomi bilan ataladi","year":"XIX asr","history":"Kolba XIX asr fransuz kimyogari Sharl Adolf Vyurts nomi bilan ataladi; u organik kimyoda, xususan Vyurts reaksiyasi bilan mashhur. Bu nom ayniqsa rus va o'zbek tilidagi darsliklarda keng qo'llanadi. Kolba qachon birinchi marta yasalgani aniq ma'lum emas.","fact":"Ingliz tilida bunday kolba ko'pincha shunchaki «distilling flask» — haydash kolbasi deb ataladi.","safety":"Haydash tizimi hech qachon butunlay yopiq bo'lmasligi kerak, aks holda bosim oshib, kolba yorilishi mumkin."},"en":{"name":"Wurtz flask","short":"A Wurtz flask is a round-bottom flask with a side tube coming out of its neck.","purpose":"It is used for distilling liquids and for producing gases. Vapour or gas leaves through the side tube to a condenser or a collecting vessel. A thermometer can be fitted in the neck to measure the vapour temperature.","material":"It is made of heat-resistant borosilicate glass, because the flask is heated strongly during distillation.","use":["Clamp the flask firmly to a stand.","Connect the side tube tightly to a condenser or a gas delivery tube.","The thermometer bulb should sit level with the side tube.","Fill no more than half full and add boiling chips."],"inventor":"Named after Charles-Adolphe Wurtz (France)","year":"19th century","history":"The flask is named after the 19th-century French chemist Charles-Adolphe Wurtz, famous in organic chemistry, for example for the Wurtz reaction. The name is used especially in Russian and Uzbek textbooks. When the flask was first made is not known exactly.","fact":"In English this flask is often simply called a distilling flask.","safety":"A distillation setup must never be completely closed, or pressure can build up and burst the flask."},"ru":{"name":"Колба Вюрца","short":"Колба Вюрца — круглодонная колба с боковой отводной трубкой на горле.","purpose":"Её используют для перегонки жидкостей и получения газов. Пар или газ выходит через отводную трубку в холодильник или приёмник. В горло можно вставить термометр, чтобы измерять температуру пара.","material":"Делается из термостойкого боросиликатного стекла, так как при перегонке колбу сильно нагревают.","use":["Надёжно закрепите колбу в лапке штатива.","Плотно присоедините отводную трубку к холодильнику или газоотводной трубке.","Шарик термометра должен находиться на уровне отводной трубки.","Наливайте не больше половины объёма и добавляйте кипелки."],"inventor":"Названа в честь Шарля Адольфа Вюрца (Франция)","year":"XIX век","history":"Колба названа в честь французского химика XIX века Шарля Адольфа Вюрца, известного работами по органической химии, например реакцией Вюрца. Это название особенно распространено в русских и узбекских учебниках. Когда именно колба была впервые изготовлена, точно неизвестно.","fact":"В английском языке такую колбу часто называют просто «колбой для перегонки» (distilling flask).","safety":"Установка для перегонки никогда не должна быть полностью закрытой, иначе давление может разорвать колбу."}},{"id":"volumetric_flask","icon":"🧴","cat":"measure","uz":{"name":"O'lchov kolbasi","short":"O'lchov kolbasi — uzun ingichka bo'g'zida bitta belgisi bor, noksimon yassi tubli kolba.","purpose":"U aniq konsentratsiyali eritmalar tayyorlash uchun ishlatiladi. Suyuqlik belgigacha to'ldirilganda kolbada aniq bir hajm (masalan, 100 yoki 250 ml) bo'ladi. U qizdirish yoki moddalarni saqlash uchun mo'ljallanmagan.","material":"Borosilikat shishadan yasaladi, ba'zan plastmassadan. Shisha kimyoviy jihatdan barqaror bo'lib, hajm o'zgarmasligi uchun kolba qizdirilmaydi.","use":["Moddani oz miqdordagi erituvchida eritib, kolbaga o'tkazing.","Belgiga yaqinlashganda suvni tomchilab qo'shing.","Suyuqlik menisksining pastki chetini ko'z darajasida belgiga to'g'rilang.","Probka bilan yopib, kolbani bir necha marta ag'darib aralashtiring."],"inventor":"Noma'lum — hajmiy analiz bilan birga rivojlangan","year":"XIX asr","history":"O'lchov kolbalari XIX asrda hajmiy (titrimetrik) analiz rivojlanishi bilan keng tarqaldi. Bu sohada Gey-Lyussak va Karl Fridrix Mor kabi kimyogarlarning ishlari muhim rol o'ynagan. O'lchov kolbasining aniq ixtirochisi ma'lum emas.","fact":"O'lchov kolbasida odatda «20 °C» yozuvi bo'ladi, chunki suyuqlik va shisha hajmi haroratga qarab biroz o'zgaradi.","safety":"O'lchov kolbasini qizdirmang — bu uning aniqligini buzadi va shisha yorilishi mumkin."},"en":{"name":"Volumetric flask","short":"A volumetric flask is a pear-shaped, flat-bottomed flask with a long narrow neck carrying a single mark.","purpose":"It is used to make solutions of exact concentration. When filled to the mark, it holds one precise volume, for example 100 or 250 mL. It is not meant for heating or storing substances.","material":"It is made of borosilicate glass, sometimes plastic. The glass is chemically stable, and the flask is not heated so its volume stays exact.","use":["Dissolve the substance in a little solvent and transfer it into the flask.","Near the mark, add water drop by drop.","Line up the bottom of the meniscus with the mark at eye level.","Stopper the flask and turn it upside down several times to mix."],"inventor":"Unknown — developed together with volumetric analysis","year":"19th century","history":"Volumetric flasks spread in the 19th century as volumetric (titration) analysis developed. Chemists such as Gay-Lussac and Karl Friedrich Mohr played an important role in this field. The exact inventor of the volumetric flask is not known.","fact":"A volumetric flask is usually marked 20 °C, because the volume of liquid and glass changes slightly with temperature.","safety":"Do not heat a volumetric flask — this spoils its accuracy and the glass may crack."},"ru":{"name":"Мерная колба","short":"Мерная колба — грушевидная плоскодонная колба с длинным узким горлом, на котором нанесена одна метка.","purpose":"Её используют для приготовления растворов точной концентрации. При заполнении до метки в колбе находится точный объём, например 100 или 250 мл. Она не предназначена для нагревания или хранения веществ.","material":"Делается из боросиликатного стекла, иногда из пластмассы. Стекло химически устойчиво, а колбу не нагревают, чтобы объём оставался точным.","use":["Растворите вещество в небольшом количестве растворителя и перенесите в колбу.","Вблизи метки добавляйте воду по каплям.","Совместите нижний край мениска с меткой на уровне глаз.","Закройте колбу пробкой и несколько раз переверните для перемешивания."],"inventor":"Неизвестен — развивалась вместе с объёмным анализом","year":"XIX век","history":"Мерные колбы распространились в XIX веке вместе с развитием объёмного (титриметрического) анализа. Важную роль в этой области сыграли работы таких химиков, как Гей-Люссак и Карл Фридрих Мор. Точный изобретатель мерной колбы неизвестен.","fact":"На мерной колбе обычно указано «20 °C», потому что объём жидкости и стекла немного меняется с температурой.","safety":"Не нагревайте мерную колбу — это нарушит её точность, а стекло может треснуть."}},{"id":"graduated_cylinder","icon":"📏","cat":"measure","uz":{"name":"O'lchov silindri","short":"O'lchov silindri — shkalasi bor, ingichka baland silindr shaklidagi o'lchov idishi.","purpose":"U suyuqlik hajmini kimyoviy stakandan ancha aniqroq o'lchash uchun ishlatiladi. Uning yordamida tajriba uchun kerakli miqdordagi suyuqlik olinadi. Juda yuqori aniqlik kerak bo'lsa, pipetka yoki byuretka ishlatiladi.","material":"Shisha (ko'pincha borosilikat) yoki shaffof plastmassadan yasaladi. Plastmassa silindrlar sinmaydi, shisha silindrlar esa kimyoviy jihatdan barqarorroq.","use":["Silindrni tekis stolga qo'ying.","Ko'zingizni suyuqlik sathi bilan bir chiziqqa keltiring.","Rangsiz suyuqlikda menisksning pastki chetiga qarab o'qing.","Silindrda moddalarni qizdirmang va aralashtirmang."],"inventor":"Noma'lum","year":"XIX asr","history":"Shkalali o'lchov idishlari kimyo miqdoriy fanga aylangan XVIII–XIX asrlarda rivojlandi. O'lchov silindri XIX asrda laboratoriyalarning standart jihoziga aylandi. Uning aniq ixtirochisi ma'lum emas.","fact":"Ko'p silindrlarning tagi olti burchakli bo'ladi — bu ularning stoldan dumalab ketishini oldini oladi.","safety":"Silindrga issiq suyuqlik quymang — shisha yorilishi va shkala noto'g'ri ko'rsatishi mumkin."},"en":{"name":"Graduated cylinder","short":"A graduated cylinder is a tall, narrow cylindrical vessel with a measuring scale.","purpose":"It is used to measure liquid volumes much more accurately than a beaker. With it you take the amount of liquid needed for an experiment. For very high accuracy, a pipette or burette is used.","material":"It is made of glass (often borosilicate) or clear plastic. Plastic cylinders do not break, while glass ones are more chemically resistant.","use":["Stand the cylinder on a flat bench.","Bring your eyes level with the liquid surface.","For clear liquids, read at the bottom of the meniscus.","Do not heat or mix substances in the cylinder."],"inventor":"Unknown","year":"19th century","history":"Measuring vessels with scales developed in the 18th–19th centuries, as chemistry became a quantitative science. The graduated cylinder was standard laboratory equipment by the 19th century. Its exact inventor is not known.","fact":"Many cylinders have a hexagonal base, which stops them from rolling off the bench.","safety":"Do not pour hot liquids into a cylinder — the glass may crack and the scale will read wrongly."},"ru":{"name":"Мерный цилиндр","short":"Мерный цилиндр — высокий узкий цилиндрический сосуд со шкалой делений.","purpose":"Его используют для измерения объёма жидкости гораздо точнее, чем химическим стаканом. С его помощью отмеряют нужное для опыта количество жидкости. Если нужна очень высокая точность, применяют пипетку или бюретку.","material":"Делается из стекла (часто боросиликатного) или прозрачной пластмассы. Пластмассовые цилиндры не бьются, а стеклянные более химически устойчивы.","use":["Ставьте цилиндр на ровный стол.","Держите глаза на уровне поверхности жидкости.","Для прозрачных жидкостей отсчёт ведите по нижнему краю мениска.","Не нагревайте и не смешивайте вещества в цилиндре."],"inventor":"Неизвестен","year":"XIX век","history":"Мерная посуда со шкалой развивалась в XVIII–XIX веках, когда химия стала количественной наукой. К XIX веку мерный цилиндр стал стандартным лабораторным оборудованием. Его точный изобретатель неизвестен.","fact":"У многих цилиндров шестиугольное основание — оно не даёт им скатиться со стола.","safety":"Не наливайте в цилиндр горячие жидкости — стекло может треснуть, а шкала будет показывать неверно."}},{"id":"burette","icon":"🧪","cat":"measure","uz":{"name":"Byuretka","short":"Byuretka — pastki uchida jo'mragi bor, uzun shkalali shisha naycha.","purpose":"Byuretka titrlashda — eritmani tomchilab qo'shib, uning aniq qancha sarflanganini o'lchashda ishlatiladi. Jo'mrak yordamida suyuqlik oqimini bir tomchigacha boshqarish mumkin. Uning aniqligi odatda 0,05 ml atrofida.","material":"Shisha (ko'pincha borosilikat)dan yasaladi, jo'mragi shisha yoki teflondan bo'ladi. Teflon jo'mrak moylashni talab qilmaydi va kimyoviy moddalarga chidamli.","use":["Byuretkani shtativga tik holda mahkamlang.","Ishlatishdan oldin uni titrlovchi eritma bilan chayqab oling.","Uchidagi havo pufakchalarini chiqarib yuboring.","Boshlang'ich va oxirgi ko'rsatkichni menisksning pastki chetidan, ko'z darajasida o'qing.","Oxiriga yaqin eritmani tomchilab qo'shing."],"inventor":"Fransua Dekruazil (Fransiya); keyin Gey-Lyussak va Karl Fridrix Mor takomillashtirgan","year":"Taxminan 1791","history":"Byuretkaning ilk shaklini fransuz kimyogari Fransua Antuan Anri Dekruazil XVIII asr oxirida yaratgan. Jozef Lui Gey-Lyussak uni takomillashtirib, «byuretka» nomini ommalashtirgan. 1850-yillarda nemis kimyogari Karl Fridrix Mor pastki qismida qisqichli byuretkani taklif qildi, bu esa titrlashni ancha qulay qildi.","fact":"«Byuretka» so'zi fransuzcha «burette» — kichik ko'za yoki idish degan so'zdan kelib chiqqan.","safety":"Byuretkani to'ldirishda uni ko'z darajasidan pastroqqa tushirib, voronka orqali to'ldiring va keyin voronkani olib qo'ying."},"en":{"name":"Burette","short":"A burette is a long graduated glass tube with a tap (stopcock) at the bottom.","purpose":"A burette is used in titration — adding a solution drop by drop and measuring exactly how much was used. The tap lets you control the flow down to a single drop. Its accuracy is usually about 0.05 mL.","material":"It is made of glass (often borosilicate), with a glass or PTFE (Teflon) tap. A PTFE tap needs no grease and resists chemicals.","use":["Clamp the burette vertically on a stand.","Rinse it with the titrant solution before use.","Remove air bubbles from the tip.","Read the start and end volumes at the bottom of the meniscus, at eye level.","Add the solution drop by drop near the end point."],"inventor":"François Descroizilles (France); later improved by Gay-Lussac and Karl Friedrich Mohr","year":"About 1791","history":"An early form of the burette was created by the French chemist François Antoine Henri Descroizilles at the end of the 18th century. Joseph Louis Gay-Lussac improved it and popularised the name burette. In the 1850s the German chemist Karl Friedrich Mohr introduced a burette with a clamp at the bottom, which made titration much easier.","fact":"The word burette comes from the French burette, meaning a small jug or flask.","safety":"Fill the burette with a funnel while it is lowered below eye level, then remove the funnel before titrating."},"ru":{"name":"Бюретка","short":"Бюретка — длинная стеклянная трубка со шкалой и краном в нижней части.","purpose":"Бюретку используют при титровании — добавлении раствора по каплям с точным измерением израсходованного объёма. Кран позволяет регулировать поток вплоть до одной капли. Её точность обычно около 0,05 мл.","material":"Делается из стекла (часто боросиликатного), кран — стеклянный или из тефлона. Тефлоновый кран не требует смазки и устойчив к химическим веществам.","use":["Закрепите бюретку в штативе строго вертикально.","Перед работой ополосните её раствором титранта.","Удалите пузырьки воздуха из носика.","Начальный и конечный отсчёт берите по нижнему краю мениска на уровне глаз.","Вблизи конечной точки добавляйте раствор по каплям."],"inventor":"Франсуа Декруазиль (Франция); позже усовершенствовали Гей-Люссак и Карл Фридрих Мор","year":"Около 1791","history":"Раннюю форму бюретки создал французский химик Франсуа Антуан Анри Декруазиль в конце XVIII века. Жозеф Луи Гей-Люссак усовершенствовал её и закрепил название «бюретка». В 1850-х годах немецкий химик Карл Фридрих Мор предложил бюретку с зажимом внизу, что сделало титрование намного удобнее.","fact":"Слово «бюретка» происходит от французского burette — «кувшинчик, сосудик».","safety":"Заполняйте бюретку через воронку, опустив её ниже уровня глаз, а перед титрованием уберите воронку."}},{"id":"pipette","icon":"💧","cat":"measure","uz":{"name":"Pipetka (Mor pipetkasi va hajmiy pipetka)","short":"Pipetka — suyuqlikning aniq hajmini o'lchab olish va o'tkazish uchun ingichka shisha naycha.","purpose":"Pipetka yordamida aniq miqdordagi suyuqlik bir idishdan boshqasiga o'tkaziladi. Mor pipetkasida (darajalangan pipetka) shkala bo'lib, turli hajmlarni o'lchash mumkin. Hajmiy pipetkaning o'rtasida kengaygan qismi va bitta belgisi bo'lib, u faqat bitta hajmni juda aniq o'lchaydi.","material":"Shishadan (ko'pincha borosilikat) yasaladi, chunki shisha kimyoviy jihatdan barqaror va shkala aniq ko'rinadi. Plastmassa pipetkalar ham bor.","use":["Suyuqlikni hech qachon og'iz bilan so'rmang — rezina noksimon so'rg'ich yoki pipetka to'ldirgichdan foydalaning.","Pipetkani o'lchanadigan eritma bilan oldindan chayqab oling.","Menisksning pastki chetini ko'z darajasida belgiga keltiring.","Hajmiy pipetkada uchida qolgan oxirgi tomchini puflab chiqarmang, agar unda boshqacha ko'rsatilmagan bo'lsa."],"inventor":"Noma'lum; Mor pipetkasi Karl Fridrix Mor (Germaniya) nomi bilan ataladi","year":"XIX asr","history":"Pipetkalar XIX asrda hajmiy analiz bilan birga asta-sekin rivojlandi. Darajalangan pipetka nemis kimyogari Karl Fridrix Mor nomi bilan bog'lanadi, u titrlash usullari va asboblarini takomillashtirgan. Hajmiy pipetkaning aniq ixtirochisi ma'lum emas.","fact":"Ko'p pipetkalarda «TD» (to deliver — chiqarish uchun) yozuvi bo'ladi: u chiqarib berilgan hajm aniq ekanini bildiradi.","safety":"Kimyoviy moddalarni hech qachon og'iz bilan pipetkaga so'rmang — doim so'rg'ichdan foydalaning."},"en":{"name":"Pipette (Mohr and volumetric pipettes)","short":"A pipette is a thin glass tube for measuring and transferring an exact volume of liquid.","purpose":"A pipette transfers a precise amount of liquid from one vessel to another. A Mohr (graduated) pipette has a scale and can measure different volumes. A volumetric pipette has a bulb in the middle and a single mark, and measures one volume very accurately.","material":"It is made of glass (often borosilicate), because glass is chemically stable and the scale is easy to read. Plastic pipettes also exist.","use":["Never pipette by mouth — use a rubber bulb or pipette filler.","Rinse the pipette with the solution to be measured first.","Bring the bottom of the meniscus to the mark at eye level.","With a volumetric pipette, do not blow out the last drop in the tip unless the pipette says so."],"inventor":"Unknown; the Mohr pipette is named after Karl Friedrich Mohr (Germany)","year":"19th century","history":"Pipettes developed gradually in the 19th century together with volumetric analysis. The graduated pipette is linked with the German chemist Karl Friedrich Mohr, who improved titration methods and apparatus. The exact inventor of the volumetric pipette is not known.","fact":"Many pipettes are marked TD (to deliver), meaning the volume that flows out is the accurate one.","safety":"Never suck chemicals into a pipette by mouth — always use a pipette filler."},"ru":{"name":"Пипетка (пипетка Мора и мерная пипетка)","short":"Пипетка — тонкая стеклянная трубка для отмеривания и переноса точного объёма жидкости.","purpose":"С помощью пипетки точное количество жидкости переносят из одного сосуда в другой. Пипетка Мора (градуированная) имеет шкалу и позволяет отмерять разные объёмы. Мерная (аналитическая) пипетка имеет расширение посередине и одну метку и очень точно отмеряет один объём.","material":"Делается из стекла (часто боросиликатного), потому что стекло химически устойчиво и шкала хорошо видна. Бывают и пластмассовые пипетки.","use":["Никогда не набирайте жидкость ртом — используйте резиновую грушу или дозатор.","Сначала ополосните пипетку отмеряемым раствором.","Совместите нижний край мениска с меткой на уровне глаз.","Из мерной пипетки не выдувайте последнюю каплю в носике, если на пипетке не указано иное."],"inventor":"Неизвестен; пипетка Мора названа в честь Карла Фридриха Мора (Германия)","year":"XIX век","history":"Пипетки постепенно развивались в XIX веке вместе с объёмным анализом. Градуированную пипетку связывают с именем немецкого химика Карла Фридриха Мора, который усовершенствовал методы и приборы титрования. Точный изобретатель мерной пипетки неизвестен.","fact":"На многих пипетках есть надпись «TD» (to deliver — «на вылив»): она означает, что точен именно вылитый объём.","safety":"Никогда не набирайте химические вещества в пипетку ртом — всегда пользуйтесь грушей."}},{"id":"dropper","icon":"💧","cat":"glass","uz":{"name":"Tomizgich","short":"Tomizgich — rezina nokchali ingichka shisha naycha bo'lib, suyuqlikni tomchilab olish va tomizish uchun ishlatiladi.","purpose":"Tomizgich bilan reaktiv yoki indikatorni oz-ozdan, tomchilab qo'shish mumkin. U titrlashda indikator tomizishda, eritmaga reaktivni ehtiyotkorlik bilan qo'shishda va namunani buyum oynasiga tomizishda qo'l keladi.","material":"Naychasi kimyoviy chidamli shishadan, nokchasi esa elastik rezinadan yasaladi. Shisha ko'p moddalar bilan reaksiyaga kirishmaydi, rezina esa siqilib-yoyilib suyuqlikni so'radi.","use":["Nokchani suyuqlikdan tashqarida siqing, keyin uchini suyuqlikka botiring.","Nokchani asta qo'yib yuborib, kerakli miqdorda suyuqlik so'rib oling.","Tomizgichni tik ushlab, nokchani sekin siqib tomchilab tomizing.","Tomizgichni hech qachon uchini yuqoriga qaratib ushlamang — suyuqlik rezinaga oqib tushadi.","Har xil reaktivlar uchun alohida tomizgich ishlating yoki uni yaxshilab yuving."],"inventor":"Noma'lum — asta-sekin takomillashgan","year":"XIX asr","history":"Suyuqlikni tomchilab olish uchun naychalar qadimdan ishlatilgan. Rezina nokchali zamonaviy tomizgich XIX asrda, rezina sanoati rivojlangach, tibbiyot va dorixonalarda keng tarqaldi. Keyinchalik u kimyo laboratoriyalarining oddiy, ammo zarur asbobiga aylandi. Uning aniq ixtirochisi ma'lum emas.","fact":"Oddiy tomizgichdan tushadigan bitta suv tomchisi taxminan 0,05 ml ga teng, ya'ni 1 ml da 20 ga yaqin tomchi bor.","safety":"Kislota yoki ishqor olingan tomizgichni boshqa reaktivga botirmang va uni hech qachon og'iz bilan so'rmang."},"en":{"name":"Dropper","short":"A dropper is a thin glass tube with a rubber bulb used to draw up a liquid and release it drop by drop.","purpose":"A dropper lets you add a reagent or indicator in very small amounts, one drop at a time. It is handy for adding indicator before a titration, for adding a reagent carefully to a solution and for placing a sample on a microscope slide.","material":"The tube is made of chemically resistant glass and the bulb of elastic rubber. Glass does not react with most substances, while the rubber bulb can be squeezed to suck liquid in and push it out.","use":["Squeeze the bulb before dipping the tip into the liquid.","Slowly release the bulb to draw up the amount you need.","Hold the dropper upright and squeeze gently to release single drops.","Never turn the dropper tip upward — the liquid will run into the rubber bulb.","Use a separate dropper for each reagent or wash it thoroughly between uses."],"inventor":"Unknown — developed gradually","year":"19th century","history":"Tubes for taking up small amounts of liquid have been used for a very long time. The modern dropper with a rubber bulb spread in medicine and pharmacies in the 19th century, after the rubber industry developed. It later became a simple but essential tool in chemistry labs. Its exact inventor is not known.","fact":"One drop of water from an ordinary dropper is about 0.05 mL, so about 20 drops make 1 mL.","safety":"Never put a dropper used for an acid or alkali into another reagent, and never suck liquid up by mouth."},"ru":{"name":"Пипетка-капельница","short":"Капельница — тонкая стеклянная трубка с резиновой грушей для набора жидкости и выпускания её по каплям.","purpose":"С помощью капельницы реактив или индикатор добавляют очень малыми порциями, по одной капле. Она удобна, чтобы добавить индикатор перед титрованием, осторожно прилить реактив к раствору или нанести образец на предметное стекло.","material":"Трубка делается из химически стойкого стекла, груша — из эластичной резины. Стекло не реагирует с большинством веществ, а резиновая груша сжимается и разжимается, набирая и выталкивая жидкость.","use":["Сожмите грушу до того, как опустить кончик в жидкость.","Медленно отпустите грушу и наберите нужное количество жидкости.","Держите капельницу вертикально и слегка сжимайте грушу, чтобы выпускать по капле.","Никогда не переворачивайте капельницу кончиком вверх — жидкость попадёт в грушу.","Для каждого реактива используйте отдельную капельницу или тщательно промывайте её."],"inventor":"Неизвестен — развивалась постепенно","year":"XIX век","history":"Трубки для набора небольших количеств жидкости используются очень давно. Современная капельница с резиновой грушей распространилась в медицине и аптеках в XIX веке, когда развилась резиновая промышленность. Позднее она стала простым, но необходимым инструментом химических лабораторий. Её точный изобретатель неизвестен.","fact":"Одна капля воды из обычной капельницы — это примерно 0,05 мл, то есть в 1 мл около 20 капель.","safety":"Не опускайте капельницу из-под кислоты или щёлочи в другой реактив и никогда не набирайте жидкость ртом."}},{"id":"funnel","icon":"🔻","cat":"filter","uz":{"name":"Kimyoviy voronka","short":"Kimyoviy voronka — keng konus va ingichka naychadan iborat idish bo'lib, suyuqlikni quyish va filtrlash uchun ishlatiladi.","purpose":"Voronka yordamida suyuqlikni tor og'izli idishga to'kmasdan quyish mumkin. Ichiga filtr qog'oz qo'yilsa, u cho'kmani eritmadan ajratish — filtrlash uchun xizmat qiladi.","material":"Ko'pincha shisha yoki kimyoviy chidamli plastmassadan (polipropilen) yasaladi. Shisha ko'p moddalarga chidamli va shaffof, plastmassa esa sinmaydi.","use":["Voronkani shtativ halqasiga yoki idish og'ziga mustahkam o'rnating.","Filtrlash uchun filtr qog'ozni to'rt buklab, konus qilib voronkaga joylang va suv bilan namlang.","Suyuqlikni shisha tayoqcha bo'ylab sekin quying.","Suyuqlik sathi filtr qog'oz chetidan 0,5–1 sm past bo'lsin.","Voronka naychasining uchi qabul qiluvchi idish devoriga tegib tursin — shunda suyuqlik sachramaydi."],"inventor":"Noma'lum — qadimdan qo'llanadi","year":"Qadimgi davr","history":"Voronkalar qadimgi zamonlardan beri sopol, metall va shishadan yasalib, sharob, moy va boshqa suyuqliklarni quyish uchun ishlatilgan. O'rta asrlarda alkimyogarlar ham ulardan foydalangan. Filtr qog'ozli shisha voronka XVIII–XIX asrlarda kimyo laboratoriyalarining asosiy asbobiga aylandi.","fact":"Burama (qovurg'ali) filtr qog'oz yoki ichki qovurg'ali voronka filtrlashni tezlashtiradi, chunki havo va suyuqlik tezroq o'tadi.","safety":"Voronkani qo'lda ushlab turib qaynoq yoki o'yuvchi suyuqlik quymang — uni shtativga mahkamlang."},"en":{"name":"Laboratory funnel","short":"A laboratory funnel is a wide cone joined to a narrow stem, used for pouring and filtering liquids.","purpose":"A funnel lets you pour a liquid into a narrow-necked container without spilling. With filter paper inside, it is used for filtration — separating a solid precipitate from a solution.","material":"It is usually made of glass or chemically resistant plastic (polypropylene). Glass resists most chemicals and is transparent, while plastic does not break.","use":["Fix the funnel firmly in a ring on a stand or in the neck of the container.","For filtering, fold filter paper into quarters, open it into a cone, place it in the funnel and wet it with water.","Pour the liquid slowly down a glass rod.","Keep the liquid level 0.5–1 cm below the edge of the filter paper.","Let the tip of the stem touch the inner wall of the receiving vessel so the liquid does not splash."],"inventor":"Unknown — used since antiquity","year":"Ancient times","history":"Funnels made of clay, metal and glass have been used since ancient times to pour wine, oil and other liquids. Medieval alchemists used them too. In the 18th–19th centuries the glass funnel with filter paper became a basic tool of the chemistry laboratory.","fact":"Fluted (pleated) filter paper or a funnel with ribs on the inside makes filtration faster, because air and liquid pass through more easily.","safety":"Do not hold the funnel by hand while pouring hot or corrosive liquids — clamp it on a stand."},"ru":{"name":"Химическая воронка","short":"Химическая воронка — широкий конус с узкой трубкой, используемый для переливания и фильтрования жидкостей.","purpose":"Воронка позволяет перелить жидкость в сосуд с узким горлом, не пролив её. Если вложить в неё фильтровальную бумагу, она служит для фильтрования — отделения осадка от раствора.","material":"Обычно её делают из стекла или химически стойкой пластмассы (полипропилена). Стекло устойчиво к большинству веществ и прозрачно, а пластмасса не бьётся.","use":["Надёжно закрепите воронку в кольце штатива или в горле сосуда.","Для фильтрования сложите фильтровальную бумагу вчетверо, расправьте конусом, вложите в воронку и смочите водой.","Наливайте жидкость медленно по стеклянной палочке.","Уровень жидкости должен быть на 0,5–1 см ниже края фильтра.","Конец трубки воронки должен касаться стенки сосуда-приёмника, чтобы жидкость не разбрызгивалась."],"inventor":"Неизвестен — используется с древности","year":"Древность","history":"Воронки из глины, металла и стекла используются с древних времён для переливания вина, масла и других жидкостей. Ими пользовались и средневековые алхимики. В XVIII–XIX веках стеклянная воронка с бумажным фильтром стала основным инструментом химической лаборатории.","fact":"Складчатый фильтр или воронка с рёбрами на внутренней стороне ускоряют фильтрование, потому что воздух и жидкость проходят легче.","safety":"Не держите воронку в руке, наливая горячие или едкие жидкости, — закрепите её в штативе."}},{"id":"separatory_funnel","icon":"🧪","cat":"filter","uz":{"name":"Ajratgich voronka","short":"Ajratgich voronka — pastida jo'mragi, tepasida tiqini bo'lgan nok yoki shar shaklidagi shisha idish bo'lib, aralashmaydigan suyuqliklarni ajratish uchun ishlatiladi.","purpose":"U bir-biri bilan aralashmaydigan, zichligi har xil suyuqliklarni (masalan, suv va moy) qatlamlarga ajratib, birma-bir to'kib olishga xizmat qiladi. Shuningdek, moddani bir erituvchidan boshqasiga o'tkazish — ekstraksiya uchun ishlatiladi.","material":"Kimyoviy va issiqqa chidamli borosilikat shishadan yasaladi, jo'mragi shisha yoki teflondan bo'ladi. Shaffof shisha orqali qatlamlar chegarasi aniq ko'rinadi.","use":["Voronkani shtativ halqasiga o'rnating va jo'mrak yopiqligini tekshiring.","Suyuqliklarni quying, tiqinni yoping va voronkani ehtiyotkorlik bilan chayqating.","Chayqatgandan keyin voronkani teskari ushlab, jo'mrakni ochib bosimni chiqaring.","Qatlamlar to'liq ajralishini kuting, keyin tiqinni oching.","Pastki qatlamni jo'mrak orqali, yuqori qatlamni esa voronka og'zidan quyib oling."],"inventor":"Noma'lum — asta-sekin takomillashgan","year":"XIX asr","history":"Aralashmaydigan suyuqliklarni ajratish uchun oddiy idishlar azaldan ishlatilgan. Jo'mrakli shisha ajratgich voronka XIX asrda organik kimyo va ekstraksiya usullari rivojlangan davrda keng tarqaldi. Uning aniq ixtirochisi ma'lum emas.","fact":"Qaysi qatlam pastda bo'lishini zichlik belgilaydi: masalan, xloroform suvdan og'ir bo'lgani uchun pastga tushadi.","safety":"Chayqatishda bosim oshadi — jo'mrakni odamlarga emas, bo'sh tomonga qaratib tez-tez ochib turing."},"en":{"name":"Separatory funnel","short":"A separatory funnel is a pear- or ball-shaped glass vessel with a tap at the bottom and a stopper at the top, used to separate liquids that do not mix.","purpose":"It separates immiscible liquids of different densities, such as water and oil, into layers that can be drained off one by one. It is also used for extraction — moving a substance from one solvent into another.","material":"It is made of chemically and heat-resistant borosilicate glass, with a glass or PTFE (Teflon) tap. The clear glass lets you see the boundary between the layers.","use":["Place the funnel in a ring on a stand and make sure the tap is closed.","Pour in the liquids, insert the stopper and shake the funnel gently.","After shaking, hold the funnel upside down and open the tap to release the pressure.","Wait until the layers have fully separated, then remove the stopper.","Drain the lower layer through the tap and pour the upper layer out through the top."],"inventor":"Unknown — developed gradually","year":"19th century","history":"Simple vessels have long been used to separate liquids that do not mix. The glass separatory funnel with a tap became widespread in the 19th century, as organic chemistry and extraction methods developed. Its exact inventor is not known.","fact":"Density decides which layer is at the bottom: chloroform, for example, is heavier than water, so it sinks.","safety":"Shaking builds up pressure — vent the funnel often, pointing the tap away from people."},"ru":{"name":"Делительная воронка","short":"Делительная воронка — грушевидный или шарообразный стеклянный сосуд с краном внизу и пробкой сверху для разделения несмешивающихся жидкостей.","purpose":"Она разделяет несмешивающиеся жидкости разной плотности, например воду и масло, на слои, которые сливают по очереди. Её также используют для экстракции — перевода вещества из одного растворителя в другой.","material":"Её делают из химически и термостойкого боросиликатного стекла, кран — из стекла или фторопласта (тефлона). Сквозь прозрачное стекло хорошо видна граница слоёв.","use":["Установите воронку в кольцо штатива и проверьте, что кран закрыт.","Налейте жидкости, закройте пробкой и осторожно встряхните.","После встряхивания переверните воронку и откройте кран, чтобы сбросить давление.","Дождитесь полного разделения слоёв и откройте пробку.","Нижний слой слейте через кран, а верхний вылейте через горло."],"inventor":"Неизвестен — развивалась постепенно","year":"XIX век","history":"Для разделения несмешивающихся жидкостей издавна применяли простые сосуды. Стеклянная делительная воронка с краном получила широкое распространение в XIX веке, когда развивались органическая химия и методы экстракции. Её точный изобретатель неизвестен.","fact":"Какой слой окажется внизу, определяет плотность: например, хлороформ тяжелее воды и опускается вниз.","safety":"При встряхивании растёт давление — чаще открывайте кран, направляя его в сторону от людей."}},{"id":"buchner_funnel","icon":"⚪","cat":"filter","uz":{"name":"Byuxner voronkasi","short":"Byuxner voronkasi — tubi ko'p teshikli tekis plastinka bo'lgan chinni voronka bo'lib, vakuum ostida tez filtrlash uchun ishlatiladi.","purpose":"U Bunzen kolbasi va nasos bilan birga cho'kmani eritmadan tez va to'liq ajratishga xizmat qiladi. Ayniqsa, kristallarni yig'ish va yuvishda qulay.","material":"An'anaviy ravishda chinnidan (farfor) yasaladi, shisha va plastmassadan ham bo'ladi. Chinni kimyoviy moddalarga chidamli, mustahkam va oson yuviladi.","use":["Voronkani rezina halqa yoki tiqin orqali Bunzen kolbasiga zich o'rnating.","Teshiklarni to'liq yopadigan, lekin devorga chiqmaydigan dumaloq filtr qog'oz qo'ying.","Filtr qog'ozni erituvchi bilan namlab, nasosni yoqing.","Aralashmani voronka markaziga quying va cho'kmani oz miqdordagi sovuq erituvchi bilan yuving.","Ishni tugatgach, avval shlangni ajrating, keyin nasosni o'chiring."],"inventor":"Ernst Byuxner (Germaniya)","year":"1888","history":"Bu voronka 1888-yilda nemis sanoat kimyogari Ernst Byuxner nomi bilan ma'lum bo'ldi. Uni vakuum bilan qo'llash filtrlashni bir necha baravar tezlashtirdi. Bugun u organik va noorganik kimyo laboratoriyalarining eng ko'p ishlatiladigan asboblaridan biri.","fact":"Ernst Byuxnerni 1907-yilda Nobel mukofotini olgan biokimyogar Eduard Buxner bilan adashtirishmaydi — ular boshqa-boshqa odamlar.","safety":"Vakuum ostidagi tizimni nasos ishlab turgan paytda ajratmang — suv nasosdan kolbaga qaytib ketishi mumkin."},"en":{"name":"Büchner funnel","short":"A Büchner funnel is a porcelain funnel with a flat plate full of holes at the bottom, used for fast filtration under vacuum.","purpose":"Together with a filter flask and a pump, it separates a solid from a liquid quickly and thoroughly. It is especially useful for collecting and washing crystals.","material":"It is traditionally made of porcelain, and also of glass or plastic. Porcelain resists chemicals, is strong and is easy to clean.","use":["Fit the funnel tightly into a filter flask using a rubber adapter or stopper.","Put in a round filter paper that covers all the holes but does not climb up the wall.","Wet the filter paper with solvent and switch on the pump.","Pour the mixture into the centre and wash the solid with a little cold solvent.","When finished, first disconnect the tubing, then switch off the pump."],"inventor":"Ernst Büchner (Germany)","year":"1888","history":"The funnel became known in 1888 under the name of the German industrial chemist Ernst Büchner. Using it with a vacuum made filtration many times faster. Today it is one of the most widely used tools in organic and inorganic chemistry labs.","fact":"Ernst Büchner is a different person from Eduard Buchner, the biochemist who won the Nobel Prize in 1907.","safety":"Do not take apart a system under vacuum while the pump is running — water can be sucked back from the pump into the flask."},"ru":{"name":"Воронка Бюхнера","short":"Воронка Бюхнера — фарфоровая воронка с плоским дырчатым дном, используемая для быстрого фильтрования под вакуумом.","purpose":"Вместе с колбой Бунзена и насосом она позволяет быстро и полно отделить осадок от жидкости. Особенно удобна для сбора и промывания кристаллов.","material":"Традиционно её делают из фарфора, а также из стекла или пластмассы. Фарфор устойчив к химическим веществам, прочен и легко моется.","use":["Плотно вставьте воронку в колбу Бунзена через резиновое кольцо или пробку.","Положите круглый фильтр, закрывающий все отверстия, но не заходящий на стенки.","Смочите фильтр растворителем и включите насос.","Вылейте смесь в центр воронки и промойте осадок небольшим количеством холодного растворителя.","По окончании сначала отсоедините шланг, затем выключите насос."],"inventor":"Эрнст Бюхнер (Германия)","year":"1888","history":"Воронка стала известна в 1888 году под именем немецкого химика-технолога Эрнста Бюхнера. Применение вакуума ускорило фильтрование в несколько раз. Сегодня это один из самых используемых приборов в лабораториях органической и неорганической химии.","fact":"Эрнст Бюхнер — не то же лицо, что биохимик Эдуард Бухнер, получивший Нобелевскую премию в 1907 году.","safety":"Не разбирайте систему под вакуумом при работающем насосе — вода может засосаться из насоса в колбу."}},{"id":"filter_flask","icon":"⚗️","cat":"filter","uz":{"name":"Bunzen kolbasi (filtrlash kolbasi)","short":"Bunzen kolbasi — yon tomonida shlang ulanadigan naychasi bor, qalin devorli konussimon shisha kolba.","purpose":"U Byuxner voronkasi bilan birga vakuum ostida filtrlash uchun ishlatiladi. Yon naycha nasosga ulanadi, filtrlangan suyuqlik esa kolbada yig'iladi.","material":"Qalin devorli borosilikat shishadan yasaladi. Qalin devor ichkaridagi past bosim va tashqi havo bosimiga bardosh beradi.","use":["Kolbani shtativga qisqich bilan mahkamlang — u yengil ag'darilib ketishi mumkin.","Yon naychani qalin devorli vakuum shlangi orqali nasosga ulang.","Kolba bilan nasos orasiga xavfsizlik kolbasini qo'yish tavsiya etiladi.","Kolba og'ziga Byuxner voronkasini rezina halqa bilan zich o'rnating.","Ishni tugatgach, avval shlangni ajratib, keyin nasosni o'chiring."],"inventor":"Robert Bunzen nomi bilan bog'liq","year":"XIX asr (1860-yillar)","history":"Kolba nemis kimyogari Robert Bunzen nomini oladi: u 1860-yillarda suv nasosi yordamida past bosimda filtrlash va cho'kmalarni yuvish usulini ishlab chiqqan. Keyinchalik bu usul Byuxner voronkasi bilan birga keng tarqaldi. Kolbaning aynan kim tomonidan birinchi yasalgani haqida aniq ma'lumot yo'q.","fact":"Oddiy konussimon kolba vakuumda yorilib ketishi mumkin, shuning uchun filtrlash kolbasining devori ancha qalin qilinadi.","safety":"Tirnalgan yoki darz ketgan kolbani vakuumda ishlatmang — u ichkariga qarab portlab sinishi mumkin."},"en":{"name":"Filter flask (Büchner flask, Bunsen flask)","short":"A filter flask is a thick-walled conical glass flask with a side arm for attaching a hose.","purpose":"It is used with a Büchner funnel for filtration under vacuum. The side arm is connected to a pump, and the filtered liquid collects inside the flask.","material":"It is made of thick-walled borosilicate glass. The thick wall withstands the difference between the low pressure inside and the air pressure outside.","use":["Clamp the flask to a stand — it tips over easily.","Connect the side arm to the pump with thick-walled vacuum tubing.","It is a good idea to place a safety (trap) flask between the flask and the pump.","Fit the Büchner funnel tightly into the neck with a rubber adapter.","When finished, first disconnect the tubing, then switch off the pump."],"inventor":"Associated with Robert Bunsen","year":"19th century (1860s)","history":"In some countries the flask is named after the German chemist Robert Bunsen, who in the 1860s developed filtering and washing precipitates under reduced pressure with a water pump. The method later spread together with the Büchner funnel. It is not known exactly who made the first flask of this shape.","fact":"An ordinary conical flask can implode under vacuum, which is why filter flasks have much thicker walls.","safety":"Never use a scratched or cracked flask under vacuum — it can implode."},"ru":{"name":"Колба Бунзена","short":"Колба Бунзена — толстостенная коническая стеклянная колба с боковым отростком для подключения шланга.","purpose":"Её используют вместе с воронкой Бюхнера для фильтрования под вакуумом. Боковой отросток соединяют с насосом, а фильтрат собирается в колбе.","material":"Её делают из толстостенного боросиликатного стекла. Толстые стенки выдерживают разницу между низким давлением внутри и атмосферным давлением снаружи.","use":["Закрепите колбу в штативе лапкой — она легко опрокидывается.","Подключите боковой отросток к насосу толстостенным вакуумным шлангом.","Между колбой и насосом желательно поставить предохранительную склянку.","Плотно вставьте воронку Бюхнера в горло через резиновое кольцо.","По окончании сначала отсоедините шланг, затем выключите насос."],"inventor":"Связана с именем Роберта Бунзена","year":"XIX век (1860-е годы)","history":"Колба носит имя немецкого химика Роберта Бунзена, который в 1860-х годах разработал способ фильтрования и промывания осадков при пониженном давлении с помощью водоструйного насоса. Позднее метод распространился вместе с воронкой Бюхнера. Кто именно первым изготовил колбу такой формы, точно неизвестно.","fact":"Обычная коническая колба может лопнуть внутрь под вакуумом, поэтому стенки колбы Бунзена делают гораздо толще.","safety":"Не используйте под вакуумом поцарапанную или треснувшую колбу — она может взорваться внутрь."}},{"id":"liebig_condenser","icon":"❄️","cat":"apparatus","uz":{"name":"Libix sovutgichi","short":"Libix sovutgichi — tashqi g'ilof ichidan sovuq suv oqib turadigan to'g'ri ichki naychadan iborat shisha sovutgich.","purpose":"U haydash (distillyatsiya) paytida bug'ni sovutib, qayta suyuqlikka aylantirish uchun ishlatiladi. Shu yo'l bilan suyuqliklar tozalanadi yoki aralashmadan ajratiladi.","material":"Issiqqa chidamli borosilikat shishadan yasaladi. U issiq bug' va sovuq suv orasidagi keskin harorat farqiga bardosh beradi, shaffofligi esa jarayonni kuzatishga imkon beradi.","use":["Sovutgichni shtativga qisqich bilan qiya holda mahkamlang.","Suv shlangini pastki naychaga, chiqish shlangini esa yuqori naychaga ulang.","Qizdirishni boshlashdan oldin suvni oqiziting.","Barcha shlif ulanishlarini tekshiring, tizim butunlay yopiq bo'lmasin.","Qizdirish to'xtatilib, apparat sovigandan keyingina suvni o'chiring."],"inventor":"Kristian Erenfrid Vaygel (Germaniya), Yustus fon Libix ommalashtirgan","year":"1771","history":"Bunday sovutgichni birinchi bo'lib 1771-yilda nemis olimi Kristian Erenfrid Vaygel tasvirlagan. Keyinchalik, XIX asrda, mashhur nemis kimyogari Yustus fon Libix uni keng qo'llab, ommalashtirdi va asbob uning nomi bilan atala boshladi. Shuning uchun ba'zan uni Vaygel–Libix sovutgichi deb ham atashadi.","fact":"Suv pastdan yuqoriga, bug'ga qarama-qarshi yo'nalishda oqizilganda g'ilof doim suvga to'la bo'ladi va sovutish samaraliroq bo'ladi.","safety":"Hech qachon butunlay yopiq tizimni qizdirmang — bosim oshib, apparat portlashi mumkin."},"en":{"name":"Liebig condenser","short":"A Liebig condenser is a glass condenser made of a straight inner tube surrounded by an outer jacket through which cold water flows.","purpose":"It is used during distillation to cool vapour and turn it back into a liquid. In this way liquids are purified or separated from mixtures.","material":"It is made of heat-resistant borosilicate glass. It withstands the sharp temperature difference between hot vapour and cold water, and its transparency lets you watch the process.","use":["Clamp the condenser to a stand at a slant.","Connect the water inlet hose to the lower nozzle and the outlet hose to the upper nozzle.","Turn on the water before you start heating.","Check all joints, and make sure the system is not completely sealed.","Turn off the water only after heating has stopped and the apparatus has cooled."],"inventor":"Christian Ehrenfried Weigel (Germany); popularised by Justus von Liebig","year":"1771","history":"This type of condenser was first described in 1771 by the German scientist Christian Ehrenfried Weigel. Later, in the 19th century, the famous German chemist Justus von Liebig used and promoted it so widely that it came to carry his name. That is why it is sometimes called the Weigel–Liebig condenser.","fact":"When water flows from bottom to top, against the vapour, the jacket stays completely full of water and cooling works better.","safety":"Never heat a completely closed system — pressure builds up and the apparatus can burst."},"ru":{"name":"Холодильник Либиха","short":"Холодильник Либиха — стеклянный холодильник из прямой внутренней трубки и внешней рубашки, по которой течёт холодная вода.","purpose":"Он служит для охлаждения пара и превращения его обратно в жидкость при перегонке (дистилляции). Так жидкости очищают или выделяют из смесей.","material":"Его делают из термостойкого боросиликатного стекла. Оно выдерживает резкую разницу температур между горячим паром и холодной водой, а прозрачность позволяет наблюдать за процессом.","use":["Закрепите холодильник в штативе под наклоном.","Подайте воду в нижний штуцер, а отводящий шланг подключите к верхнему.","Включите воду до начала нагревания.","Проверьте все соединения; система не должна быть полностью герметичной.","Выключайте воду только после прекращения нагрева и остывания прибора."],"inventor":"Кристиан Эренфрид Вайгель (Германия); популяризировал Юстус фон Либих","year":"1771","history":"Такой холодильник впервые описал в 1771 году немецкий учёный Кристиан Эренфрид Вайгель. Позднее, в XIX веке, знаменитый немецкий химик Юстус фон Либих так широко применял и распространял его, что прибор стали называть его именем. Поэтому его иногда называют холодильником Вайгеля–Либиха.","fact":"Когда вода течёт снизу вверх, навстречу пару, рубашка полностью заполнена водой и охлаждение эффективнее.","safety":"Никогда не нагревайте полностью закрытую систему — давление вырастет, и прибор может разорваться."}},{"id":"retort","icon":"⚗️","cat":"glass","uz":{"name":"Retorta","short":"Retorta — uzun, pastga egilgan bo'yinli sharsimon idish bo'lib, moddalarni qizdirib haydash uchun ishlatiladi.","purpose":"Retortada modda qizdirilganda hosil bo'lgan bug' egilgan bo'yin orqali o'tib soviydi va qabul qiluvchi idishga suyuqlik bo'lib tushadi. U qadimda haydash va moddalarni parchalash uchun asosiy asbob bo'lgan, bugun ko'proq ta'lim va tarixiy namoyishlarda ishlatiladi.","material":"Laboratoriya retortalari issiqqa chidamli shishadan, sanoatdagilari esa sopol yoki metalldan yasaladi. Shisha qizdirishga chidaydi va ichini ko'rishga imkon beradi.","use":["Retortani shtativga mahkamlab, ostidan bir tekis qizdiring.","Bo'yin uchini sovuq suvga qo'yilgan qabul qiluvchi idishga yo'naltiring.","Retortani yarmidan ko'p to'ldirmang.","Qizdirishni sekin boshlang va to'satdan sovutmang."],"inventor":"Noma'lum — alkimyogarlar qo'llagan","year":"O'rta asrlar","history":"Retorta qadimgi va o'rta asr alkimyogarlarining eng mashhur asbobi bo'lgan, uning ildizlari yunon-misr va islom olami alkimyosiga borib taqaladi. Undan atirlar, kislotalar va turli moddalarni olishda foydalanilgan. XIX asrda ancha qulay sovutgichli haydash apparatlari paydo bo'lgach, retorta laboratoriyalarda kam ishlatila boshladi.","fact":"Retorta kimyo va alkimyoning ramzi sifatida ko'plab gerb, kitob va logotiplarda tasvirlanadi.","safety":"Retortani qizdirishda bo'yin uchi hech qachon yopiq bo'lmasin va unga yuz bilan yaqin egilmang."},"en":{"name":"Retort","short":"A retort is a round vessel with a long neck bent downward, used for heating and distilling substances.","purpose":"When a substance is heated in a retort, the vapour travels down the bent neck, cools and drips as a liquid into a receiver. It was once the main tool for distilling and decomposing substances; today it is mostly used in teaching and historical demonstrations.","material":"Laboratory retorts are made of heat-resistant glass, while industrial ones are made of ceramic or metal. Glass tolerates heating and lets you see inside.","use":["Clamp the retort on a stand and heat it evenly from below.","Direct the end of the neck into a receiver standing in cold water.","Do not fill the retort more than halfway.","Start heating slowly and never cool it suddenly."],"inventor":"Unknown — used by alchemists","year":"Middle Ages","history":"The retort was the best-known tool of ancient and medieval alchemists, with roots in Greco-Egyptian and Islamic alchemy. It was used to make perfumes, acids and many other substances. In the 19th century more convenient distillation set-ups with condensers appeared, and the retort became less common in laboratories.","fact":"The retort is a symbol of chemistry and alchemy and appears on many coats of arms, book covers and logos.","safety":"When heating a retort, never close the end of the neck and never lean your face over it."},"ru":{"name":"Реторта","short":"Реторта — шарообразный сосуд с длинным, загнутым вниз горлом для нагревания и перегонки веществ.","purpose":"При нагревании вещества в реторте пар проходит по изогнутому горлу, охлаждается и стекает жидкостью в приёмник. Когда-то она была главным прибором для перегонки и разложения веществ, сегодня её применяют в основном в обучении и исторических опытах.","material":"Лабораторные реторты делают из термостойкого стекла, промышленные — из керамики или металла. Стекло выдерживает нагрев и позволяет видеть содержимое.","use":["Закрепите реторту в штативе и нагревайте её равномерно снизу.","Направьте конец горла в приёмник, стоящий в холодной воде.","Не заполняйте реторту больше чем наполовину.","Начинайте нагрев медленно и не охлаждайте её резко."],"inventor":"Неизвестен — использовалась алхимиками","year":"Средние века","history":"Реторта была самым известным прибором древних и средневековых алхимиков; её истоки восходят к греко-египетской и исламской алхимии. С её помощью получали духи, кислоты и многие другие вещества. В XIX веке появились более удобные перегонные установки с холодильниками, и реторту стали применять реже.","fact":"Реторта — символ химии и алхимии, её изображают на гербах, обложках книг и логотипах.","safety":"При нагревании никогда не закрывайте конец горла реторты и не наклоняйтесь над ней."}},{"id":"evaporating_dish","icon":"🥣","cat":"porcelain","uz":{"name":"Chinni kosacha","short":"Chinni kosacha — tumshuqchali, tekis tubli sayoz chinni idish bo'lib, eritmalarni bug'latish uchun ishlatiladi.","purpose":"Unda eritma qizdirilib, erituvchi bug'latiladi va erigan modda qattiq holda ajratib olinadi. Masalan, osh tuzi eritmasidan tuz kristallarini olish mumkin.","material":"Chinnidan (farfor) yasaladi, ichki tomoni sirlangan bo'ladi. Chinni kuchli qizdirishga chidaydi, kislotalar ta'sirida yemirilmaydi, sirlangan sirt esa oson tozalanadi.","use":["Kosachani asbest-to'r yoki uchburchak ustiga qo'yib qizdiring.","Uni yarmidan ko'p to'ldirmang.","Bug'lanish oxirida sachramasligi uchun shisha tayoqcha bilan aralashtirib turing.","Issiq kosachani tigel qisqichi bilan oling va sovuq yuzaga qo'ymang."],"inventor":"Noma'lum — asta-sekin takomillashgan","year":"XVIII–XIX asr","history":"Eritmalarni bug'latish uchun sayoz idishlar qadimdan, masalan, tuz olishda ishlatilgan. Yevropada chinni ishlab chiqarish XVIII asrda yo'lga qo'yilgach, chinni laboratoriya idishlari keng tarqaldi. Chinni kosacha XIX asrda kimyo laboratoriyalarining odatiy asbobiga aylandi.","fact":"Kosachaning keng va sayoz shakli bug'lanish yuzasini oshiradi, shuning uchun suyuqlik tez bug'lanadi.","safety":"Bug'lanishning oxirida qizdirishni kamaytiring — qolgan modda sachrab, ko'zga tushishi mumkin, himoya ko'zoynagini taqing."},"en":{"name":"Evaporating dish","short":"An evaporating dish is a shallow porcelain dish with a flat bottom and a small spout, used to evaporate solutions.","purpose":"A solution is heated in it so the solvent evaporates and the dissolved substance is left behind as a solid. For example, you can obtain salt crystals from a salt solution.","material":"It is made of porcelain, glazed on the inside. Porcelain withstands strong heating and is not attacked by acids, and the glazed surface is easy to clean.","use":["Heat the dish on a wire gauze or a pipe-clay triangle.","Do not fill it more than halfway.","Stir with a glass rod near the end of evaporation to prevent spitting.","Lift a hot dish with crucible tongs and do not put it on a cold surface."],"inventor":"Unknown — developed gradually","year":"18th–19th century","history":"Shallow vessels have been used to evaporate solutions since ancient times, for example to make salt. After porcelain production was established in Europe in the 18th century, porcelain lab ware spread widely. The evaporating dish became a standard piece of chemistry lab equipment in the 19th century.","fact":"The wide, shallow shape gives a large surface area, so the liquid evaporates faster.","safety":"Reduce the heat near the end of evaporation — the residue can spit into your eyes, so wear safety goggles."},"ru":{"name":"Фарфоровая выпарительная чашка","short":"Выпарительная чашка — неглубокая фарфоровая чашка с плоским дном и носиком для выпаривания растворов.","purpose":"В ней нагревают раствор, растворитель испаряется, а растворённое вещество остаётся в твёрдом виде. Например, так получают кристаллы соли из её раствора.","material":"Её делают из фарфора, глазурованного изнутри. Фарфор выдерживает сильный нагрев и не разрушается кислотами, а глазурь легко очищается.","use":["Нагревайте чашку на асбестированной сетке или фарфоровом треугольнике.","Не заполняйте её больше чем наполовину.","В конце выпаривания помешивайте стеклянной палочкой, чтобы избежать разбрызгивания.","Горячую чашку берите тигельными щипцами и не ставьте на холодную поверхность."],"inventor":"Неизвестен — развивалась постепенно","year":"XVIII–XIX века","history":"Неглубокие сосуды для выпаривания растворов используются с древности, например для добычи соли. После того как в XVIII веке в Европе наладили производство фарфора, фарфоровая лабораторная посуда получила широкое распространение. В XIX веке выпарительная чашка стала обычным прибором химической лаборатории.","fact":"Широкая и мелкая форма даёт большую поверхность испарения, поэтому жидкость испаряется быстрее.","safety":"В конце выпаривания уменьшите нагрев — остаток может брызнуть в глаза, работайте в защитных очках."}},{"id":"mortar_pestle","icon":"🥣","cat":"porcelain","uz":{"name":"Chinni hovoncha va dasta","short":"Chinni hovoncha va dasta — qattiq moddalarni maydalash va ishqalab kukun qilish uchun ishlatiladigan qalin devorli kosa va tayoqcha.","purpose":"Ular yordamida kristall va bo'lak moddalar mayda kukunga aylantiriladi. Kukun suvda tezroq eriydi va reaksiyaga tezroq kirishadi, shuningdek, bir necha qattiq moddani bir xil aralashtirish mumkin.","material":"Laboratoriyada ko'pincha chinnidan, ba'zan agat yoki shishadan yasaladi. Chinni qattiq, ko'p moddalarga chidamli, ichki g'adir-budur yuzasi esa maydalashni osonlashtiradi.","use":["Hovonchaga moddadan oz miqdorda soling — uchdan biridan ko'p emas.","Dastani urmasdan, aylantirib bosib ishqalang.","Hovonchani bir qo'l bilan mahkam ushlab turing.","Har xil moddalar uchun hovonchani yaxshilab yuvib, quriting."],"inventor":"Noma'lum — qadimdan qo'llanadi","year":"Qadimgi davr","history":"Hovoncha va dasta insoniyatning eng qadimgi asboblaridan biri bo'lib, toshdan yasalgan namunalari ming yillar avval don va o'simliklarni maydalashda ishlatilgan. Tabiblar, dorishunoslar va alkimyogarlar ulardan dori va bo'yoqlar tayyorlashda foydalanishgan. Chinni hovonchalar keyinchalik dorixona va kimyo laboratoriyalarida keng tarqaldi.","fact":"Hovoncha va dasta ko'p mamlakatlarda dorixonaning ramzi hisoblanadi.","safety":"Oksidlovchilarni (masalan, kaliy permanganat yoki kaliy xlorat) organik moddalar yoki oltingugurt bilan birga hech qachon maydalamang — portlash yuz berishi mumkin."},"en":{"name":"Mortar and pestle","short":"A mortar and pestle are a thick-walled bowl and a club-shaped tool used to crush and grind solids into powder.","purpose":"They turn crystals and lumps into a fine powder. A powder dissolves and reacts faster, and several solids can be mixed evenly this way.","material":"In the lab they are usually made of porcelain, sometimes of agate or glass. Porcelain is hard and resists most chemicals, and its rough unglazed inner surface makes grinding easier.","use":["Put only a small amount of substance in the mortar — no more than a third full.","Grind by pressing and rotating the pestle, not by pounding.","Hold the mortar firmly with your other hand.","Wash and dry the mortar thoroughly before grinding a different substance."],"inventor":"Unknown — used since antiquity","year":"Ancient times","history":"The mortar and pestle is one of humanity's oldest tools: stone versions were used thousands of years ago to grind grain and plants. Healers, apothecaries and alchemists used them to prepare medicines and pigments. Porcelain mortars later became common in pharmacies and chemistry labs.","fact":"In many countries the mortar and pestle is the symbol of the pharmacy.","safety":"Never grind oxidisers (such as potassium permanganate or potassium chlorate) together with organic substances or sulfur — this can cause an explosion."},"ru":{"name":"Фарфоровая ступка с пестиком","short":"Ступка с пестиком — толстостенная чаша и палочка для измельчения и растирания твёрдых веществ в порошок.","purpose":"Ими превращают кристаллы и комки в мелкий порошок. Порошок быстрее растворяется и реагирует, а несколько твёрдых веществ можно так равномерно перемешать.","material":"В лаборатории их обычно делают из фарфора, иногда из агата или стекла. Фарфор твёрдый и устойчив к большинству веществ, а шероховатая неглазурованная внутренняя поверхность облегчает растирание.","use":["Кладите в ступку немного вещества — не больше трети её объёма.","Растирайте круговыми движениями с нажимом, а не ударами.","Крепко придерживайте ступку другой рукой.","Перед растиранием другого вещества тщательно вымойте и высушите ступку."],"inventor":"Неизвестен — используется с древности","year":"Древность","history":"Ступка с пестиком — один из древнейших инструментов человечества: каменными ступками тысячи лет назад растирали зерно и растения. Лекари, аптекари и алхимики готовили в них лекарства и краски. Позднее фарфоровые ступки широко распространились в аптеках и химических лабораториях.","fact":"Во многих странах ступка с пестиком — символ аптеки.","safety":"Никогда не растирайте окислители (например, перманганат или хлорат калия) вместе с органическими веществами или серой — возможен взрыв."}},{"id":"crucible","icon":"🔥","cat":"porcelain","uz":{"name":"Tigel","short":"Tigel — qopqoqli kichik chinni idish bo'lib, moddalarni juda yuqori haroratda qizdirish va kuydirish uchun ishlatiladi.","purpose":"Tigelda qattiq moddalar kuchli qizdiriladi, kuydiriladi yoki suyuqlantiriladi. U miqdoriy tahlilda cho'kmani doimiy massagacha qizdirish va moddalarning tarkibini aniqlashda ishlatiladi.","material":"Ko'pincha chinnidan, shuningdek, kvars, grafit, platina yoki nikeldan yasaladi. Chinni 1000 °C dan yuqori haroratga chidaydi va ko'p moddalar bilan reaksiyaga kirishmaydi.","use":["Tigelni chinni uchburchak ustiga qo'yib, gorelka alangasida qizdiring.","Qizdirishni sekin boshlang, keyin alangani kuchaytiring.","Tigelni faqat tigel qisqichi bilan oling.","Issiq tigelni sovitish uchun eksikatorga yoki issiqqa chidamli taglikka qo'ying.","Tortishdan oldin tigelni xona haroratigacha sovuting."],"inventor":"Noma'lum — qadimdan qo'llanadi","year":"Qadimgi davr","history":"Sopol tigellar bir necha ming yil avval mis, bronza va boshqa metallarni suyuqlantirishda ishlatilgan. O'rta asrlarda alkimyogarlar va zargarlar ham tigeldan keng foydalanishgan. Zamonaviy chinni tigellar XIX asrda analitik kimyoning muhim asbobiga aylandi.","fact":"Ingliz tilidagi crucible so'zi ko'chma ma'noda og'ir sinov degan ma'noni ham bildiradi.","safety":"Qizigan tigelni qo'l bilan ushlamang va uni to'satdan sovuq suvga yoki sovuq yuzaga qo'ymang — u yorilib ketadi."},"en":{"name":"Crucible","short":"A crucible is a small porcelain container with a lid, used to heat and ignite substances at very high temperatures.","purpose":"Solids are strongly heated, burned or melted in a crucible. In quantitative analysis it is used to heat a precipitate to constant mass and to determine the composition of substances.","material":"It is usually made of porcelain, and also of quartz, graphite, platinum or nickel. Porcelain withstands temperatures above 1000 °C and does not react with most substances.","use":["Place the crucible on a pipe-clay triangle and heat it in a burner flame.","Start heating gently, then increase the flame.","Handle the crucible only with crucible tongs.","Put the hot crucible in a desiccator or on a heat-resistant mat to cool.","Let the crucible cool to room temperature before weighing."],"inventor":"Unknown — used since antiquity","year":"Ancient times","history":"Clay crucibles were used thousands of years ago to melt copper, bronze and other metals. In the Middle Ages alchemists and goldsmiths used crucibles widely. Modern porcelain crucibles became an important tool of analytical chemistry in the 19th century.","fact":"In English the word crucible is also used figuratively to mean a severe test or trial.","safety":"Never touch a hot crucible with your hands or put it suddenly into cold water or on a cold surface — it will crack."},"ru":{"name":"Тигель","short":"Тигель — небольшой фарфоровый сосуд с крышкой для нагревания и прокаливания веществ при очень высоких температурах.","purpose":"В тигле твёрдые вещества сильно нагревают, прокаливают или плавят. В количественном анализе в нём прокаливают осадок до постоянной массы и определяют состав веществ.","material":"Чаще всего его делают из фарфора, а также из кварца, графита, платины или никеля. Фарфор выдерживает температуру выше 1000 °C и не реагирует с большинством веществ.","use":["Поставьте тигель на фарфоровый треугольник и нагревайте в пламени горелки.","Начинайте нагрев осторожно, затем усиливайте пламя.","Берите тигель только тигельными щипцами.","Горячий тигель ставьте остывать в эксикатор или на термостойкую подставку.","Перед взвешиванием охладите тигель до комнатной температуры."],"inventor":"Неизвестен — используется с древности","year":"Древность","history":"Глиняные тигли использовали тысячи лет назад для плавки меди, бронзы и других металлов. В Средние века тиглями широко пользовались алхимики и ювелиры. Современные фарфоровые тигли стали важным прибором аналитической химии в XIX веке.","fact":"Английское слово crucible в переносном смысле означает суровое испытание.","safety":"Не трогайте горячий тигель руками и не опускайте его резко в холодную воду или на холодную поверхность — он треснет."}},{"id":"crucible_tongs","icon":"🗜️","cat":"support","uz":{"name":"Tigel qisqichi","short":"Tigel qisqichi — uchlari egilgan uzun metall qisqich bo'lib, issiq tigel va kosachalarni ushlash uchun ishlatiladi.","purpose":"U qattiq qizdirilgan tigel, chinni kosacha va boshqa issiq buyumlarni xavfsiz ko'tarish va ko'chirish uchun xizmat qiladi. Uzun dastalari qo'lni alanga va issiqdan uzoqda tutadi.","material":"Zanglamaydigan po'lat yoki nikellangan temirdan yasaladi. Metall yuqori haroratda erimaydi va mustahkam, zanglamaydigan qoplama esa uni korroziyadan saqlaydi.","use":["Tigelni yon tomonidan, egilgan uchlari bilan mahkam qisib oling.","Qisqichni ishlatishdan oldin uchlari toza va quruqligini tekshiring.","Issiq buyumni sekin va gorizontal holda ko'chiring.","Ishlatgandan keyin qisqichni issiqqa chidamli taglikka qo'ying — uchlari hali issiq bo'ladi."],"inventor":"Noma'lum — temirchilik qisqichlaridan kelib chiqqan","year":"Qadimgi davr","history":"Issiq metall va tigellarni ushlash uchun qisqichlar qadimgi temirchilar va metallurglar tomonidan ishlatilgan. Laboratoriya tigel qisqichi aynan shu asboblarning kichik va qulay ko'rinishidir. U XIX asrda analitik kimyo rivojlanishi bilan har bir laboratoriyaning oddiy jihoziga aylandi.","fact":"Ko'p tigel qisqichlarining uchlari egik qilib yasaladi — bu tigelni yon tomonidan ham, yuqoridan ham ishonchli ushlashga imkon beradi.","safety":"Qisqich uchlarini qizdirilgandan keyin qo'l bilan ushlamang — metall issiqlikni yaxshi o'tkazadi va kuydirib qo'yadi."},"en":{"name":"Crucible tongs","short":"Crucible tongs are long metal tongs with curved tips, used to hold hot crucibles and dishes.","purpose":"They are used to lift and move strongly heated crucibles, evaporating dishes and other hot objects safely. The long handles keep your hands away from the flame and heat.","material":"They are made of stainless steel or nickel-plated iron. Metal does not melt at high temperatures and is strong, and the stainless finish protects against corrosion.","use":["Grip the crucible firmly from the side with the curved tips.","Check that the tips are clean and dry before use.","Move the hot object slowly and keep it level.","After use, put the tongs on a heat-resistant mat — the tips are still hot."],"inventor":"Unknown — developed from blacksmiths' tongs","year":"Ancient times","history":"Tongs for holding hot metal and crucibles were used by ancient blacksmiths and metalworkers. Laboratory crucible tongs are a small, handy version of those tools. They became standard equipment in every lab in the 19th century as analytical chemistry developed.","fact":"The tips of many crucible tongs are bent so the crucible can be held securely both from the side and from above.","safety":"Do not touch the tips after heating — metal conducts heat well and can burn you."},"ru":{"name":"Тигельные щипцы","short":"Тигельные щипцы — длинные металлические щипцы с изогнутыми концами для захвата горячих тиглей и чашек.","purpose":"Ими безопасно поднимают и переносят сильно нагретые тигли, выпарительные чашки и другие горячие предметы. Длинные ручки держат руки подальше от пламени и жара.","material":"Их делают из нержавеющей стали или никелированного железа. Металл не плавится при высокой температуре и прочен, а нержавеющее покрытие защищает от коррозии.","use":["Плотно захватывайте тигель сбоку изогнутыми концами.","Перед работой проверьте, что концы чистые и сухие.","Переносите горячий предмет медленно, держа его ровно.","После работы кладите щипцы на термостойкую подставку — концы ещё горячие."],"inventor":"Неизвестен — произошли от кузнечных клещей","year":"Древность","history":"Клещами для захвата горячего металла и тиглей пользовались ещё древние кузнецы и металлурги. Лабораторные тигельные щипцы — это уменьшенный и удобный вариант этих инструментов. С развитием аналитической химии в XIX веке они стали обычным оснащением каждой лаборатории.","fact":"Концы многих тигельных щипцов изогнуты, чтобы тигель можно было надёжно держать и сбоку, и сверху.","safety":"Не трогайте концы щипцов после нагрева — металл хорошо проводит тепло и может обжечь."}},{"id":"watch_glass","icon":"🔍","cat":"glass","uz":{"name":"Soat oynasi","short":"Soat oynasi — dumaloq, biroz botiq shaklli yupqa shisha bo'lib, oz miqdordagi moddalar bilan ishlash uchun ishlatiladi.","purpose":"Unda oz miqdordagi suyuqlik bug'latiladi, qattiq modda tortiladi yoki kristallar kuzatiladi. Shuningdek, u kimyoviy stakan uchun qopqoq vazifasini bajarib, ichiga chang tushishidan saqlaydi.","material":"Shaffof shishadan, ba'zan issiqqa chidamli borosilikat shishadan yasaladi. Shisha kimyoviy chidamli va shaffof, shuning uchun moddani yaxshi ko'rish mumkin.","use":["Soat oynasini tekis va toza yuzaga qo'ying.","Unga oz miqdorda modda yoki bir necha tomchi eritma soling.","Stakan qopqog'i sifatida botiq tomonini pastga qaratib qo'ying.","Soat oynasini to'g'ridan-to'g'ri alangada qizdirmang."],"inventor":"Noma'lum — nomi cho'ntak soati oynasidan olingan","year":"XVIII–XIX asr","history":"Bu asbob nomini eski cho'ntak soatlarining qavariq himoya oynasidan olgan — shakli aynan shunday. Kimyogarlar bunday arzon va qulay oynalardan oz miqdordagi moddalar bilan ishlashda foydalana boshlashgan. Uning aniq ixtirochisi ma'lum emas.","fact":"Ikki soat oynasini chetlarini birlashtirib, qisqich bilan mahkamlansa, kichik yopiq idish hosil bo'ladi.","safety":"Soat oynasi yupqa va mo'rt — uni ehtiyotkorlik bilan ushlang, singan bo'laklarni qo'l bilan yig'mang."},"en":{"name":"Watch glass","short":"A watch glass is a thin, round, slightly concave piece of glass used for working with small amounts of substances.","purpose":"It is used to evaporate a small amount of liquid, to weigh a solid or to observe crystals. It can also serve as a lid for a beaker to keep dust out.","material":"It is made of clear glass, sometimes heat-resistant borosilicate glass. Glass is chemically resistant and transparent, so the substance is easy to see.","use":["Place the watch glass on a flat, clean surface.","Put a small amount of substance or a few drops of solution on it.","When using it as a beaker lid, place it concave side down.","Do not heat a watch glass directly in a flame."],"inventor":"Unknown — named after the glass of a pocket watch","year":"18th–19th century","history":"The tool gets its name from the curved protective glass of old pocket watches, which has the same shape. Chemists began to use these cheap, handy glasses for working with small amounts of substances. Its exact inventor is not known.","fact":"Two watch glasses placed rim to rim and held with a clip make a small closed container.","safety":"A watch glass is thin and fragile — handle it carefully and never pick up broken pieces with your bare hands."},"ru":{"name":"Часовое стекло","short":"Часовое стекло — тонкое круглое слегка вогнутое стекло для работы с небольшими количествами веществ.","purpose":"На нём выпаривают небольшое количество жидкости, взвешивают твёрдое вещество или наблюдают кристаллы. Его также используют как крышку для химического стакана, чтобы туда не попадала пыль.","material":"Его делают из прозрачного стекла, иногда из термостойкого боросиликатного. Стекло химически устойчиво и прозрачно, поэтому вещество хорошо видно.","use":["Кладите часовое стекло на ровную чистую поверхность.","Помещайте на него небольшое количество вещества или несколько капель раствора.","Используя его как крышку стакана, кладите вогнутой стороной вниз.","Не нагревайте часовое стекло прямо в пламени."],"inventor":"Неизвестен — название от стекла карманных часов","year":"XVIII–XIX века","history":"Своё название прибор получил от выпуклого защитного стекла старинных карманных часов, имеющего такую же форму. Химики стали использовать эти дешёвые и удобные стёкла для работы с малыми количествами веществ. Точный изобретатель неизвестен.","fact":"Если сложить два часовых стекла краями и скрепить зажимом, получится маленький закрытый сосуд.","safety":"Часовое стекло тонкое и хрупкое — обращайтесь с ним осторожно и не собирайте осколки голыми руками."}},{"id":"petri_dish","icon":"🧫","cat":"glass","uz":{"name":"Petri kosachasi","short":"Petri kosachasi — qopqoqli, sayoz, dumaloq shisha yoki plastmassa idish bo'lib, asosan mikroorganizmlarni o'stirish uchun ishlatiladi.","purpose":"Biologiya va mikrobiologiyada unda ozuqa muhiti (masalan, agar) ustida bakteriya va zamburug'lar o'stiriladi. Kimyoda esa u oz miqdordagi moddalarni kuzatish, kristallarni o'stirish va sayoz idish sifatida ishlatiladi.","material":"Shishadan yoki shaffof polistirol plastmassadan yasaladi. Shisha kosachalarni qizdirib sterillash mumkin, plastmassalari esa bir martalik bo'lib, oldindan sterillangan holda chiqariladi.","use":["Kosachani ochishdan oldin qo'llaringizni yuving yoki qo'lqop kiying.","Qopqoqni to'liq olmasdan, faqat biroz qiya ochib ishlang.","Kosachani tagiga yozuv yozing — qopqog'iga emas.","Mikroorganizm o'stirilgan kosachalarni teskari qilib saqlang, shunda tomchilar ozuqa muhitiga tushmaydi."],"inventor":"Yulius Rixard Petri (Germaniya)","year":"1887","history":"Bu kosachani 1887-yilda nemis bakteriologi Yulius Rixard Petri taklif qilgan. U mashhur olim Robert Koxning yordamchisi bo'lib ishlagan. Qopqoqli sayoz kosacha bakteriyalarni toza holda o'stirishni ancha osonlashtirdi va tez orada butun dunyoga tarqaldi.","fact":"1928-yilda Aleksandr Fleming Petri kosachasidagi mog'or bakteriyalarni o'ldirayotganini payqab, penitsillinni kashf etgan.","safety":"Mikroorganizm o'stirilgan kosachani laboratoriyadan tashqarida ochmang va ishlatilganidan keyin ularni o'qituvchi ko'rsatmasiga ko'ra zararsizlantiring."},"en":{"name":"Petri dish","short":"A Petri dish is a shallow round glass or plastic dish with a lid, used mainly for growing microorganisms.","purpose":"In biology and microbiology, bacteria and fungi are grown in it on a nutrient medium such as agar. In chemistry it is used to observe small amounts of substances, to grow crystals and as a shallow container.","material":"It is made of glass or clear polystyrene plastic. Glass dishes can be sterilised by heating, while plastic ones are disposable and come pre-sterilised.","use":["Wash your hands or wear gloves before opening the dish.","Do not remove the lid completely — just lift it slightly at an angle.","Write labels on the bottom of the dish, not on the lid.","Store dishes with cultures upside down so that drops of water do not fall onto the medium."],"inventor":"Julius Richard Petri (Germany)","year":"1887","history":"The dish was introduced in 1887 by the German bacteriologist Julius Richard Petri. He worked as an assistant to the famous scientist Robert Koch. The shallow dish with a lid made it much easier to grow pure cultures of bacteria and soon spread around the world.","fact":"In 1928 Alexander Fleming discovered penicillin after noticing that a mould in a Petri dish was killing bacteria.","safety":"Never open a dish with cultures outside the lab, and dispose of used dishes as your teacher instructs."},"ru":{"name":"Чашка Петри","short":"Чашка Петри — неглубокая круглая стеклянная или пластмассовая чашка с крышкой, используемая в основном для выращивания микроорганизмов.","purpose":"В биологии и микробиологии в ней выращивают бактерии и грибы на питательной среде, например на агаре. В химии её используют для наблюдения за небольшими количествами веществ, выращивания кристаллов и как неглубокий сосуд.","material":"Её делают из стекла или прозрачного полистирола. Стеклянные чашки можно стерилизовать нагреванием, а пластиковые одноразовые и выпускаются уже стерильными.","use":["Перед тем как открыть чашку, вымойте руки или наденьте перчатки.","Не снимайте крышку полностью — лишь слегка приоткрывайте её под углом.","Подписывайте дно чашки, а не крышку.","Чашки с посевами храните дном вверх, чтобы капли воды не падали на среду."],"inventor":"Юлиус Рихард Петри (Германия)","year":"1887","history":"Чашку предложил в 1887 году немецкий бактериолог Юлиус Рихард Петри. Он работал ассистентом знаменитого учёного Роберта Коха. Неглубокая чашка с крышкой значительно упростила выращивание чистых культур бактерий и вскоре распространилась по всему миру.","fact":"В 1928 году Александр Флеминг открыл пенициллин, заметив, что плесень в чашке Петри убивает бактерии.","safety":"Не открывайте чашку с посевами вне лаборатории и утилизируйте использованные чашки по указанию учителя."}},{"id":"bunsen_burner","icon":"🔥","cat":"heat","uz":{"name":"Bunzen gorelkasi","short":"Bunzen gorelkasi — gaz yoqib, issiq va tutunsiz alanga beradigan laboratoriya gorelkasi.","purpose":"U probirka, kolba va tigellardagi moddalarni qizdirish, eritmalarni qaynatish va shishani yumshatish uchun ishlatiladi. Havo teshigini ochib-yopib, alanga haroratini boshqarish mumkin. Ko'k alanga eng issiq qismi bo'lib, taxminan 1500 °C gacha yetadi.","material":"Asosan metalldan (latun yoki po'lat) yasaladi, chunki metall issiqqa chidamli va pishiq. Og'ir asosi gorelkani ag'darilishdan saqlaydi.","use":["Gorelkani issiqqa chidamli, tekis stol ustiga qo'ying va gaz shlangini mahkam ulang.","Havo teshigini yoping, gugurt yoki zajigalkani yoqib, keyin gazni oching.","Havo teshigini asta ochib, sariq alangani ko'k alangaga aylantiring.","Qizdirishda alanganing ko'k konus uchidan biroz yuqoridagi eng issiq qismidan foydalaning.","Ish tugagach, gaz kranini to'liq yoping."],"inventor":"Robert Bunzen va mexanik Peter Desaga (Germaniya)","year":"1855","history":"1855-yilda Geydelberg universitetida Robert Bunzen yangi laboratoriya binosi uchun gorelka loyihalashtirgan, uni universitet mexanigi Peter Desaga yasagan. Asosiy g'oya — gazni yonishdan oldin havo bilan aralashtirish edi, shu tufayli alanga issiq va tutunsiz bo'ldi. Bunzen bu gorelkadan spektral tahlilda foydalangan va Kirxgof bilan birga seziy va rubidiy elementlarini kashf etgan.","fact":"Bunzen gorelkasining tutunsiz alangasi elementlarning rangli spektrini ko'rishga imkon berdi va bu yangi elementlar kashf qilinishiga yordam berdi.","safety":"Yonib turgan gorelkani hech qachon qarovsiz qoldirmang, uzun sochni yig'ing va yonuvchi moddalarni alangadan uzoq tuting."},"en":{"name":"Bunsen burner","short":"A Bunsen burner is a laboratory gas burner that produces a hot, smokeless flame.","purpose":"It is used to heat substances in test tubes, flasks and crucibles, to boil solutions and to soften glass. The flame temperature is controlled by opening or closing the air hole. The blue flame is the hottest and can reach about 1500 °C.","material":"It is mostly made of metal (brass or steel), which is heat-resistant and durable. The heavy base keeps the burner from tipping over.","use":["Place the burner on a flat, heat-resistant bench and attach the gas hose firmly.","Close the air hole, light a match or lighter, then open the gas.","Slowly open the air hole to turn the yellow flame into a blue one.","Heat with the hottest region, just above the tip of the inner blue cone.","When finished, turn the gas tap off completely."],"inventor":"Robert Bunsen and instrument maker Peter Desaga (Germany)","year":"1855","history":"In 1855 at the University of Heidelberg, Robert Bunsen designed a burner for the new chemistry laboratory, and the university mechanic Peter Desaga built it. The key idea was to mix the gas with air before burning, which made the flame hot and smokeless. Bunsen used the burner for spectral analysis and, together with Kirchhoff, discovered the elements caesium and rubidium.","fact":"The smokeless flame of the Bunsen burner made it possible to see the coloured spectra of elements, which led to the discovery of new elements.","safety":"Never leave a lit burner unattended, tie back long hair and keep flammable substances away from the flame."},"ru":{"name":"Горелка Бунзена","short":"Горелка Бунзена — лабораторная газовая горелка, дающая горячее и некоптящее пламя.","purpose":"Её используют для нагревания веществ в пробирках, колбах и тиглях, кипячения растворов и размягчения стекла. Температуру пламени регулируют, открывая или закрывая отверстие для воздуха. Голубое пламя самое горячее и достигает примерно 1500 °C.","material":"Обычно изготавливается из металла (латуни или стали), который устойчив к нагреву и прочен. Тяжёлое основание не даёт горелке опрокинуться.","use":["Поставьте горелку на ровный жаростойкий стол и плотно присоедините газовый шланг.","Закройте отверстие для воздуха, зажгите спичку или зажигалку, затем откройте газ.","Медленно открывайте отверстие для воздуха, чтобы жёлтое пламя стало голубым.","Нагревайте самой горячей зоной — чуть выше вершины внутреннего голубого конуса.","После работы полностью закройте газовый кран."],"inventor":"Роберт Бунзен и механик Петер Дезага (Германия)","year":"1855","history":"В 1855 году в Гейдельбергском университете Роберт Бунзен разработал горелку для новой химической лаборатории, а университетский механик Петер Дезага её изготовил. Главная идея — смешивать газ с воздухом до сгорания, благодаря чему пламя стало горячим и некоптящим. Бунзен применял горелку в спектральном анализе и вместе с Кирхгофом открыл цезий и рубидий.","fact":"Некоптящее пламя горелки Бунзена позволило увидеть цветные спектры элементов, что привело к открытию новых элементов.","safety":"Никогда не оставляйте зажжённую горелку без присмотра, убирайте длинные волосы и держите горючие вещества подальше от пламени."}},{"id":"spirit_lamp","icon":"🕯️","cat":"heat","uz":{"name":"Spirt lampasi","short":"Spirt lampasi — spirt yoqib, kichik va tinch alanga beradigan oddiy qizdirish asbobi.","purpose":"U gaz bo'lmagan joyda moddalarni ozgina qizdirish, probirkadagi eritmani isitish va kichik tajribalar uchun ishlatiladi. Alangasi Bunzen gorelkasinikidan sovuqroq, shuning uchun kuchli qizdirish talab qilinmaydigan ishlarga mos.","material":"Idishi shisha yoki metalldan, piligi paxta ipidan, qopqog'i shisha yoki metalldan yasaladi. Qopqoq spirtning bug'lanib ketishini to'xtatadi va alangani o'chiradi.","use":["Lampani faqat spirt bilan, idishning taxminan 2/3 qismigacha to'ldiring.","Pilikni gugurt bilan yoqing — boshqa yonib turgan lampadan hech qachon yoqmang.","Qizdirishda alanganing yuqori uchinchi qismidan foydalaning.","O'chirish uchun qopqoqni ustiga yoping, hech qachon puflamang."],"inventor":"Noma'lum — asta-sekin rivojlangan","year":"XVIII–XIX asrlar","history":"Moy chiroqlari qadimdan ma'lum, spirt yoqiladigan lampalar esa spirt keng ishlab chiqarila boshlagach paydo bo'lgan. XVIII–XIX asrlarda ular dorixonalar va laboratoriyalarda keng qo'llangan. Gaz gorelkalari tarqalgach ham spirt lampasi maktab laboratoriyalarida oddiy va arzon asbob sifatida saqlanib qoldi.","fact":"Spirt alangasi deyarli tutunsiz yonadi, shuning uchun idish tagini qoraytirmaydi.","safety":"Yonib turgan lampaga spirt quymang va uni yonib turgan holda boshqa joyga ko'chirmang."},"en":{"name":"Spirit lamp (alcohol burner)","short":"A spirit lamp is a simple heating device that burns alcohol to give a small, steady flame.","purpose":"It is used for gentle heating where there is no gas supply, for warming a solution in a test tube and for small experiments. Its flame is cooler than a Bunsen burner flame, so it suits tasks that do not need strong heating.","material":"The body is glass or metal, the wick is cotton, and the cap is glass or metal. The cap stops the alcohol from evaporating and puts out the flame.","use":["Fill the lamp only with alcohol, to about two thirds of its volume.","Light the wick with a match — never from another burning lamp.","Heat using the upper third of the flame.","To put it out, cover it with the cap; never blow on it."],"inventor":"Unknown — developed gradually","year":"18th–19th centuries","history":"Oil lamps have been known since antiquity, while lamps burning alcohol appeared once alcohol was produced widely. In the 18th and 19th centuries they were common in pharmacies and laboratories. Even after gas burners spread, the spirit lamp stayed in school laboratories as a simple and cheap tool.","fact":"An alcohol flame burns almost without soot, so it does not blacken the bottom of the vessel.","safety":"Never refill a burning lamp and never carry it around while it is lit."},"ru":{"name":"Спиртовка","short":"Спиртовка — простой нагревательный прибор, который сжигает спирт и даёт небольшое ровное пламя.","purpose":"Её используют для слабого нагревания там, где нет газа, для подогрева раствора в пробирке и в небольших опытах. Пламя спиртовки холоднее, чем у горелки Бунзена, поэтому она подходит для работ без сильного нагрева.","material":"Резервуар делают из стекла или металла, фитиль — из хлопковой нити, колпачок — из стекла или металла. Колпачок не даёт спирту испаряться и гасит пламя.","use":["Заполняйте спиртовку только спиртом, примерно на две трети объёма.","Зажигайте фитиль спичкой — никогда от другой горящей спиртовки.","Нагревайте верхней третью пламени.","Гасите, накрывая колпачком; никогда не задувайте."],"inventor":"Неизвестен — прибор развивался постепенно","year":"XVIII–XIX века","history":"Масляные светильники известны с древности, а лампы, сжигающие спирт, появились, когда спирт стали широко производить. В XVIII–XIX веках они были обычными в аптеках и лабораториях. Даже после распространения газовых горелок спиртовка осталась в школьных лабораториях как простой и дешёвый прибор.","fact":"Спирт горит почти без копоти, поэтому дно сосуда не чернеет.","safety":"Не доливайте спирт в горящую спиртовку и не переносите её зажжённой."}},{"id":"retort_stand","icon":"🏗️","cat":"support","uz":{"name":"Laboratoriya shtativi (qisqich va halqa bilan)","short":"Laboratoriya shtativi — og'ir asos va tik metall sterjendan iborat, qisqich va halqa yordamida asboblarni ushlab turadigan tayanch.","purpose":"U kolba, byuretka, voronka, sovutgich kabi asboblarni kerakli balandlikda mahkam ushlab turish uchun xizmat qiladi. Halqaga voronka yoki to'r qo'yiladi, qisqich esa kolba yoki byuretkani tutadi. Shu tufayli asboblarni qo'lda ushlamasdan xavfsiz ishlash mumkin.","material":"Asos va sterjen po'lat yoki cho'yandan yasaladi — og'irlik barqarorlik beradi. Qisqichlarning ichki qismi ko'pincha rezina yoki probka bilan qoplanadi, shunda shisha sinmaydi.","use":["Shtativni stolning tekis joyiga qo'ying, asbobni asos ustida joylashtiring.","Mufta yordamida qisqich yoki halqani kerakli balandlikka mahkamlang.","Shisha asbobni qisqichga qo'yib, vintni sinmasligi uchun ehtiyotkorlik bilan burang.","Og'ir yukni asos ustida ushlang, aks holda shtativ ag'darilishi mumkin."],"inventor":"Noma'lum — asta-sekin rivojlangan","year":"XIX asr","history":"Kimyogarlar qadimdan idishlarni turli tayanchlarga o'rnatib kelgan. Hozirgi ko'rinishdagi sterjenli shtativ qisqich va muftalar bilan birga XIX asrda laboratoriya kimyosi rivojlanishi bilan keng tarqaldi. Ingliz tilida u ba'zan retort stand deb ataladi, chunki ilgari unga retortalar o'rnatilgan.","fact":"Bitta shtativga bir nechta qisqich o'rnatib, butun bir qurilmani — masalan, haydash uskunasini — yig'ish mumkin.","safety":"Qisqichni haddan tashqari qattiq burab shisha asbobni sindirmang va shtativning ag'darilmasligini tekshiring."},"en":{"name":"Retort stand (with clamp and ring)","short":"A retort stand is a support made of a heavy base and an upright metal rod that holds equipment using clamps and rings.","purpose":"It holds flasks, burettes, funnels, condensers and other equipment firmly at the right height. A funnel or gauze rests on the ring, while a clamp grips a flask or burette. This lets you work safely without holding the equipment by hand.","material":"The base and rod are made of steel or cast iron — the weight gives stability. Clamp jaws are often lined with rubber or cork so that glass does not break.","use":["Place the stand on a flat part of the bench, with the equipment above the base.","Fix the clamp or ring at the needed height with a boss head.","Put the glassware into the clamp and tighten the screw gently so it does not crack.","Keep heavy loads over the base, otherwise the stand may tip over."],"inventor":"Unknown — developed gradually","year":"19th century","history":"Chemists have long mounted vessels on various supports. The modern rod stand with clamps and boss heads became widespread in the 19th century as laboratory chemistry developed. It is called a retort stand because retorts were once mounted on it.","fact":"With several clamps on one stand you can build a whole set-up, for example a distillation apparatus.","safety":"Do not overtighten the clamp and crack the glass, and check that the stand cannot tip over."},"ru":{"name":"Лабораторный штатив (с лапкой и кольцом)","short":"Лабораторный штатив — опора из тяжёлого основания и вертикального металлического стержня, удерживающая приборы с помощью лапок и колец.","purpose":"Он прочно удерживает колбы, бюретки, воронки, холодильники и другие приборы на нужной высоте. На кольцо ставят воронку или сетку, а лапка зажимает колбу или бюретку. Так можно безопасно работать, не держа приборы в руках.","material":"Основание и стержень делают из стали или чугуна — вес обеспечивает устойчивость. Губки лапок часто покрывают резиной или пробкой, чтобы не разбить стекло.","use":["Поставьте штатив на ровное место стола, прибор располагайте над основанием.","Закрепите лапку или кольцо муфтой на нужной высоте.","Вставьте стеклянный прибор в лапку и аккуратно затяните винт, чтобы стекло не треснуло.","Держите тяжёлый груз над основанием, иначе штатив может опрокинуться."],"inventor":"Неизвестен — прибор развивался постепенно","year":"XIX век","history":"Химики издавна закрепляли сосуды на разных подставках. Современный штатив со стержнем, лапками и муфтами широко распространился в XIX веке вместе с развитием лабораторной химии. По-английски его называют retort stand, потому что раньше на нём закрепляли реторты.","fact":"Закрепив на одном штативе несколько лапок, можно собрать целую установку, например для перегонки.","safety":"Не перетягивайте лапку, чтобы не раздавить стекло, и проверьте, что штатив не опрокинется."}},{"id":"tripod_gauze","icon":"🔺","cat":"support","uz":{"name":"Uchoyoq va asbestsiz metall to'r","short":"Uchoyoq — uch oyoqli metall tayanch, uning ustiga qo'yiladigan metall to'r esa qizdirilayotgan idishni ushlab, issiqlikni bir tekis tarqatadi.","purpose":"Uchoyoq gorelka ustida kimyoviy stakan, kolba yoki chinni kosachani ushlab turadi. To'r alanga issiqligini idish tagiga bir tekis taqsimlaydi va shishani to'g'ridan-to'g'ri alangadan himoya qiladi. Bu shisha idishning yorilib ketishini oldini oladi.","material":"Uchoyoq va to'r issiqqa chidamli po'latdan yasaladi. Ilgari to'r markazi asbest bilan qoplangan, ammo asbest sog'liq uchun zararli bo'lgani uchun hozir keramik qoplamali yoki oddiy metall to'r ishlatiladi.","use":["Uchoyoqni tekis joyga qo'ying va gorelkani uning ostiga joylashtiring.","To'rni uchoyoq ustiga tekis qo'ying.","Idishni to'rning markaziga qo'ying, keyin gorelkani yoqing.","Qizdirishdan keyin uchoyoq va to'r uzoq vaqt issiq turadi — ularni sovuguncha ushlamang."],"inventor":"Noma'lum — asta-sekin rivojlangan","year":"XIX asr","history":"Idishlarni olov ustida uch oyoqli tayanchlarda ushlash usuli qadimdan ma'lum. Gaz gorelkalari tarqalgan XIX asrda laboratoriya uchoyog'i va metall to'r standart jihozga aylandi. XX asr oxirida asbest xavfi aniqlangach, ko'plab mamlakatlarda asbestli to'rlar keramik va asbestsiz to'rlarga almashtirildi.","fact":"Uch oyoqli tayanch notekis sirtda ham chayqalmaydi, chunki uch nuqta har doim bitta tekislikda yotadi.","safety":"Asbestli eski to'rlardan foydalanmang, issiq uchoyoq va to'rni faqat qisqich bilan yoki sovuganidan keyin ushlang."},"en":{"name":"Tripod and asbestos-free wire gauze","short":"A tripod is a three-legged metal stand, and the wire gauze placed on it holds a vessel being heated and spreads the heat evenly.","purpose":"The tripod holds a beaker, flask or evaporating dish above a burner. The gauze spreads the heat of the flame evenly over the bottom of the vessel and protects glass from the direct flame. This helps stop glassware from cracking.","material":"The tripod and gauze are made of heat-resistant steel. Gauzes once had an asbestos centre, but because asbestos harms health, ceramic-centred or plain metal gauzes are used today.","use":["Stand the tripod on a flat surface and place the burner underneath it.","Lay the gauze flat on top of the tripod.","Put the vessel in the centre of the gauze, then light the burner.","The tripod and gauze stay hot for a long time after heating — do not touch them until they cool."],"inventor":"Unknown — developed gradually","year":"19th century","history":"Holding vessels over a fire on three-legged supports has been known since ancient times. In the 19th century, as gas burners spread, the laboratory tripod and wire gauze became standard equipment. In the late 20th century, once the danger of asbestos was recognised, many countries replaced asbestos gauzes with ceramic and asbestos-free ones.","fact":"A three-legged stand never wobbles, even on an uneven surface, because three points always lie in one plane.","safety":"Do not use old asbestos gauzes, and handle a hot tripod and gauze only with tongs or after they have cooled."},"ru":{"name":"Треножник и металлическая сетка без асбеста","short":"Треножник — металлическая подставка на трёх ножках, а сетка на нём удерживает нагреваемый сосуд и равномерно распределяет тепло.","purpose":"Треножник удерживает химический стакан, колбу или фарфоровую чашку над горелкой. Сетка равномерно распределяет тепло пламени по дну сосуда и защищает стекло от прямого огня. Это помогает избежать растрескивания стеклянной посуды.","material":"Треножник и сетку делают из жаростойкой стали. Раньше центр сетки покрывали асбестом, но так как асбест вреден для здоровья, сейчас используют сетки с керамическим покрытием или простые металлические.","use":["Поставьте треножник на ровную поверхность и разместите под ним горелку.","Положите сетку ровно на треножник.","Поставьте сосуд в центр сетки, затем зажгите горелку.","После нагревания треножник и сетка долго остаются горячими — не трогайте их, пока не остынут."],"inventor":"Неизвестен — прибор развивался постепенно","year":"XIX век","history":"Сосуды над огнём на трёхногих подставках держали ещё в древности. В XIX веке, с распространением газовых горелок, лабораторный треножник и металлическая сетка стали стандартным оборудованием. В конце XX века, когда была признана опасность асбеста, во многих странах асбестовые сетки заменили керамическими и безасбестовыми.","fact":"Трёхногая подставка не шатается даже на неровной поверхности, потому что три точки всегда лежат в одной плоскости.","safety":"Не используйте старые асбестовые сетки, а горячие треножник и сетку берите только щипцами или после остывания."}},{"id":"kipp_apparatus","icon":"⚗️","cat":"apparatus","uz":{"name":"Kipp apparati","short":"Kipp apparati — qattiq modda va suyuqlik reaksiyasidan gazni kerak bo'lganda olish uchun mo'ljallangan shisha qurilma.","purpose":"Unda vodorod (rux va xlorid kislotadan), karbonat angidrid (marmar va xlorid kislotadan) yoki vodorod sulfid kabi gazlar olinadi. Kran ochilganda gaz chiqadi, yopilganda gaz bosimi kislotani siqib chiqaradi va reaksiya o'z-o'zidan to'xtaydi. Shu sababli gazni kerakli paytda va kerakli miqdorda olish mumkin.","material":"Qalin devorli shishadan yasaladi, chunki shisha kislotalarga chidamli va ichidagi jarayonni ko'rishga imkon beradi. Qalin devor gaz bosimiga bardosh beradi.","use":["O'rta sharga qattiq moddani (masalan, rux bo'laklarini) soling.","Yuqori voronka orqali kislotani quying.","Kranni ochib, gazni kerakli idishga yo'naltiring.","Kranni yopsangiz, kislota pastga siqilib, reaksiya to'xtaydi."],"inventor":"Petrus Yakobus Kipp (Niderlandiya)","year":"1844","history":"Gollandiyalik farmatsevt Petrus Yakobus Kipp 1844-yilda bu qurilmani yaratgan. Uning qulayligi shundaki, gaz kerak bo'lmaganda reaksiya avtomatik ravishda to'xtaydi. Kipp apparati XIX va XX asrlarda kimyo laboratoriyalarida gaz olishning asosiy usullaridan biri bo'lib qoldi.","fact":"Kipp apparati o'z-o'zini boshqaradi: gaz bosimining o'zi kislotani qattiq moddadan ajratib, reaksiyani to'xtatadi.","safety":"Vodorod havo bilan portlovchi aralashma hosil qiladi — uni yoqishdan oldin tozaligini tekshiring va apparatni alangadan uzoq tuting."},"en":{"name":"Kipp's apparatus","short":"Kipp's apparatus is a glass device for producing a gas on demand from the reaction of a solid with a liquid.","purpose":"It is used to make gases such as hydrogen (from zinc and hydrochloric acid), carbon dioxide (from marble and hydrochloric acid) or hydrogen sulfide. When the tap is open, gas flows out; when it is closed, the gas pressure pushes the acid away and the reaction stops by itself. So you get gas exactly when and as much as you need.","material":"It is made of thick-walled glass, because glass resists acids and lets you watch the process. The thick walls withstand the gas pressure.","use":["Put the solid (for example, pieces of zinc) into the middle bulb.","Pour acid in through the top funnel.","Open the tap and lead the gas to the vessel you need.","When you close the tap, the acid is pushed down and the reaction stops."],"inventor":"Petrus Jacobus Kipp (Netherlands)","year":"1844","history":"The Dutch pharmacist Petrus Jacobus Kipp created this device in 1844. Its great advantage is that the reaction stops automatically when no gas is needed. Kipp's apparatus remained one of the main ways of producing gases in chemistry laboratories throughout the 19th and 20th centuries.","fact":"Kipp's apparatus regulates itself: the gas pressure alone separates the acid from the solid and stops the reaction.","safety":"Hydrogen forms explosive mixtures with air — test its purity before lighting it and keep the apparatus away from flames."},"ru":{"name":"Аппарат Киппа","short":"Аппарат Киппа — стеклянный прибор для получения газа по мере надобности из реакции твёрдого вещества с жидкостью.","purpose":"В нём получают водород (из цинка и соляной кислоты), углекислый газ (из мрамора и соляной кислоты) или сероводород. Когда кран открыт, газ выходит; когда закрыт, давление газа вытесняет кислоту и реакция сама прекращается. Поэтому газ можно получать именно тогда и столько, сколько нужно.","material":"Изготавливается из толстостенного стекла, потому что стекло устойчиво к кислотам и позволяет наблюдать процесс. Толстые стенки выдерживают давление газа.","use":["Поместите твёрдое вещество (например, кусочки цинка) в средний шар.","Налейте кислоту через верхнюю воронку.","Откройте кран и направьте газ в нужный сосуд.","Когда кран закрыт, кислота вытесняется вниз и реакция прекращается."],"inventor":"Петрус Якобус Кипп (Нидерланды)","year":"1844","history":"Нидерландский фармацевт Петрус Якобус Кипп создал этот прибор в 1844 году. Его главное достоинство — реакция автоматически прекращается, когда газ не нужен. Аппарат Киппа оставался одним из основных способов получения газов в химических лабораториях в XIX и XX веках.","fact":"Аппарат Киппа саморегулируется: само давление газа отделяет кислоту от твёрдого вещества и останавливает реакцию.","safety":"Водород образует с воздухом взрывчатые смеси — проверяйте его чистоту перед поджиганием и держите аппарат вдали от огня."}},{"id":"desiccator","icon":"🫙","cat":"glass","uz":{"name":"Eksikator","short":"Eksikator — moddalarni quruq holda saqlash yoki quritish uchun zich yopiladigan qopqoqli qalin shisha idish.","purpose":"Uning pastki qismiga namni yutuvchi modda (silikagel, suvsiz kalsiy xlorid yoki boshqalar) solinadi. Yuqoridagi chinni plastinkaga qo'yilgan modda havodagi namni yutmaydi. Ayniqsa qizdirilgan tigellarni tortishdan oldin sovutish uchun ishlatiladi.","material":"Qalin shisha yoki plastmassadan yasaladi. Qopqoq va idish chetlari silliqlangan bo'lib, maxsus moy bilan surtiladi — shunda havo kirmaydi.","use":["Pastki qismga quritgich moddani soling va ustiga chinni plastinkani qo'ying.","Qopqoq chetiga yupqa qatlam maxsus moy surting.","Qopqoqni ko'tarmasdan, yon tomonga surib oching va yoping.","Rangli silikagel rangi o'zgarsa, uni almashtiring yoki quriting."],"inventor":"Noma'lum — asta-sekin rivojlangan","year":"XIX asr","history":"Moddalarni namdan himoya qilish kimyoviy tahlilning aniqligi uchun muhim bo'lgan. XIX asrda analitik kimyo rivojlanishi bilan eksikatorlar laboratoriyalarda keng tarqaldi. Keyinchalik havosi so'rib olinadigan vakuum-eksikatorlar ham paydo bo'ldi.","fact":"Ko'k rangli silikagel namni yutganda pushti rangga kiradi — bu quritgichni almashtirish vaqti kelganini ko'rsatadi.","safety":"Qopqoqni ehtiyot bilan surib oching va issiq tigelni qo'ygandan keyin qopqoq ko'tarilib ketmasligi uchun uni bir oz ushlab turing."},"en":{"name":"Desiccator","short":"A desiccator is a thick glass vessel with a tightly fitting lid for keeping or drying substances in dry air.","purpose":"A drying agent (silica gel, anhydrous calcium chloride or others) is placed in the bottom. A substance placed on the porcelain plate above does not absorb moisture from the air. It is especially used to cool heated crucibles before weighing them.","material":"It is made of thick glass or plastic. The rims of the lid and body are ground smooth and greased so that no air gets in.","use":["Put the drying agent in the bottom and place the porcelain plate above it.","Spread a thin layer of grease on the rim of the lid.","Open and close the lid by sliding it sideways, not by lifting it.","Replace or dry indicating silica gel when its colour changes."],"inventor":"Unknown — developed gradually","year":"19th century","history":"Protecting substances from moisture has always mattered for accurate chemical analysis. In the 19th century, with the growth of analytical chemistry, desiccators became widespread in laboratories. Later, vacuum desiccators, from which the air can be pumped out, also appeared.","fact":"Blue indicating silica gel turns pink when it has absorbed moisture — a sign that the drying agent needs replacing.","safety":"Slide the lid open carefully, and hold it for a moment after putting in a hot crucible so the warm air does not push it off."},"ru":{"name":"Эксикатор","short":"Эксикатор — толстостенный стеклянный сосуд с плотно притёртой крышкой для хранения и высушивания веществ в сухом воздухе.","purpose":"На дно помещают осушитель (силикагель, безводный хлорид кальция и другие). Вещество на фарфоровой вкладке над ним не поглощает влагу из воздуха. Особенно часто в эксикаторе охлаждают прокалённые тигли перед взвешиванием.","material":"Изготавливается из толстого стекла или пластмассы. Края крышки и корпуса пришлифованы и смазываются специальной смазкой, чтобы не проходил воздух.","use":["Насыпьте осушитель на дно и положите сверху фарфоровую вкладку.","Нанесите тонкий слой смазки на шлиф крышки.","Открывайте и закрывайте крышку, сдвигая её вбок, а не поднимая.","Замените или высушите индикаторный силикагель, когда изменится его цвет."],"inventor":"Неизвестен — прибор развивался постепенно","year":"XIX век","history":"Защита веществ от влаги всегда была важна для точного химического анализа. В XIX веке с развитием аналитической химии эксикаторы широко распространились в лабораториях. Позже появились и вакуум-эксикаторы, из которых можно откачать воздух.","fact":"Синий индикаторный силикагель становится розовым, когда насыщается влагой, — значит, осушитель пора менять.","safety":"Осторожно сдвигайте крышку, а поставив горячий тигель, придержите её немного, чтобы тёплый воздух её не сдвинул."}},{"id":"thermometer","icon":"🌡️","cat":"measure","uz":{"name":"Laboratoriya termometri","short":"Laboratoriya termometri — suyuqlik, eritma yoki bug'ning haroratini o'lchaydigan shisha asbob.","purpose":"U reaksiya aralashmasi, qaynayotgan yoki muzlayotgan modda haroratini o'lchash uchun ishlatiladi. Haydash paytida bug' haroratini kuzatib, moddalarni ajratishga yordam beradi. Erish va qaynash nuqtalarini aniqlashda ham kerak.","material":"Ingichka shisha naycha ichida rangli spirt yoki simob bo'ladi — ular qizisa kengayib, shkala bo'ylab ko'tariladi. Hozir xavfsizlik uchun ko'pincha simobsiz termometrlar yoki elektron termometrlar ishlatiladi.","use":["Termometrni o'lchanayotgan suyuqlikka shunday botiringki, uning uchi idish tubiga tegmasin.","Ko'rsatkich barqarorlashguncha kuting.","Shkaladagi raqamni ko'z darajasida turib o'qing.","Termometrni aralashtirgich sifatida ishlatmang — u oson sinadi."],"inventor":"Bir necha olimlar: Galileo Galiley (termoskop), Daniel Gabriel Farengeyt (simobli termometr), Anders Selsiy (shkala)","year":"XVII–XVIII asrlar","history":"Taxminan 1593-yilda haroratni ko'rsatadigan termoskop paydo bo'lgan, u odatda Galileo Galiley nomi bilan bog'lanadi, ammo shunga o'xshash asboblarni boshqa olimlar ham yaratgan. 1714-yilda Daniel Gabriel Farengeyt simobli termometrni yaratdi. 1742-yilda Anders Selsiy 100 bo'linmali shkalani taklif qildi, keyinchalik u hozirgi ko'rinishga keltirildi.","fact":"Selsiy dastlab suvning qaynash nuqtasini 0, muzlash nuqtasini 100 deb belgilagan — keyinchalik shkala teskari o'girilgan.","safety":"Simobli termometr sinsa, simobni qo'l bilan ushlamang va darhol o'qituvchiga xabar bering."},"en":{"name":"Laboratory thermometer","short":"A laboratory thermometer is a glass instrument for measuring the temperature of liquids, solutions or vapours.","purpose":"It measures the temperature of a reaction mixture or of a substance that is boiling or freezing. During distillation it tracks the vapour temperature and helps separate substances. It is also needed to find melting and boiling points.","material":"A thin glass tube contains coloured alcohol or mercury, which expands when heated and rises along the scale. Today mercury-free or electronic thermometers are often used for safety.","use":["Dip the thermometer into the liquid so that its bulb does not touch the bottom of the vessel.","Wait until the reading is steady.","Read the scale with your eye at the level of the liquid column.","Never use the thermometer as a stirring rod — it breaks easily."],"inventor":"Several scientists: Galileo Galilei (thermoscope), Daniel Gabriel Fahrenheit (mercury thermometer), Anders Celsius (scale)","year":"17th–18th centuries","history":"Around 1593 the thermoscope, which showed changes in temperature, appeared; it is usually linked with Galileo Galilei, although other scholars made similar devices. In 1714 Daniel Gabriel Fahrenheit made the mercury thermometer. In 1742 Anders Celsius proposed a 100-division scale, which was later turned into its present form.","fact":"Celsius originally set the boiling point of water at 0 and the freezing point at 100 — the scale was later reversed.","safety":"If a mercury thermometer breaks, do not touch the mercury and tell your teacher immediately."},"ru":{"name":"Лабораторный термометр","short":"Лабораторный термометр — стеклянный прибор для измерения температуры жидкостей, растворов или паров.","purpose":"Им измеряют температуру реакционной смеси, кипящего или замерзающего вещества. При перегонке он показывает температуру паров и помогает разделять вещества. Он также нужен для определения температур плавления и кипения.","material":"В тонкой стеклянной трубке находится подкрашенный спирт или ртуть, которые при нагревании расширяются и поднимаются по шкале. Сейчас ради безопасности часто используют безртутные или электронные термометры.","use":["Опустите термометр в жидкость так, чтобы его резервуар не касался дна сосуда.","Дождитесь, пока показание установится.","Снимайте показание, держа глаза на уровне столбика.","Не используйте термометр вместо мешалки — он легко ломается."],"inventor":"Несколько учёных: Галилео Галилей (термоскоп), Даниель Габриель Фаренгейт (ртутный термометр), Андерс Цельсий (шкала)","year":"XVII–XVIII века","history":"Около 1593 года появился термоскоп, показывавший изменение температуры; его обычно связывают с Галилео Галилеем, хотя похожие приборы создавали и другие учёные. В 1714 году Даниель Габриель Фаренгейт создал ртутный термометр. В 1742 году Андерс Цельсий предложил шкалу из 100 делений, которую позже привели к современному виду.","fact":"Цельсий сначала принял температуру кипения воды за 0, а замерзания — за 100; позже шкалу перевернули.","safety":"Если ртутный термометр разбился, не трогайте ртуть руками и сразу сообщите учителю."}},{"id":"dewar_flask","icon":"🧊","cat":"glass","uz":{"name":"Dyuar idishi","short":"Dyuar idishi — devorlari orasida vakuum bo'lgan, ichidagi moddaning haroratini uzoq saqlaydigan qo'sh devorli idish.","purpose":"Laboratoriyada u suyuq azot kabi juda sovuq suyuqliklarni saqlash va tashish uchun ishlatiladi. Vakuum issiqlik o'tishini deyarli to'xtatadi, shuning uchun suyuqlik sekin bug'lanadi. Uyda ishlatiladigan termos ham shu tamoyil asosida ishlaydi.","material":"Qo'sh devorli shisha yoki zanglamaydigan po'latdan yasaladi. Devorlar orasidan havo so'rib olinadi, shisha devorlar esa issiqlik nurlanishini qaytarish uchun kumushlanadi.","use":["Idishni faqat tik holda va barqaror joyga qo'ying.","Sovuq suyuqlikni asta-sekin quying, chunki idish avval soviydi.","Qopqoqni germetik yopmang — bug'langan gaz chiqib turishi kerak.","Idishni urib olmang: shisha devor sinsa, vakuum tufayli parchalar sochilishi mumkin."],"inventor":"Jeyms Dyuar (Shotlandiya, Buyuk Britaniya)","year":"1892","history":"Shotland olimi Jeyms Dyuar 1892-yilda gazlarni suyuqlantirish bo'yicha tadqiqotlarida sovuq suyuqliklarni saqlash uchun bu idishni yaratgan. U o'z ixtirosini patentlamagan. 1904-yilda Germaniyada shu tamoyil asosida uy-ro'zg'or termoslarini ishlab chiqaruvchi Thermos kompaniyasi tashkil topdi.","fact":"Dyuar idishi yordamida Jeyms Dyuar 1898-yilda birinchi bo'lib vodorodni suyuq holatga keltirgan.","safety":"Suyuq azot bilan ishlaganda himoya ko'zoynagi va maxsus qo'lqop taqing — u terini bir zumda muzlatib yuboradi."},"en":{"name":"Dewar flask","short":"A Dewar flask is a double-walled vessel with a vacuum between the walls that keeps its contents at the same temperature for a long time.","purpose":"In the laboratory it is used to store and carry very cold liquids such as liquid nitrogen. The vacuum almost stops heat transfer, so the liquid evaporates slowly. The household vacuum flask works on the same principle.","material":"It is made of double-walled glass or stainless steel. The air between the walls is pumped out, and glass walls are silvered to reflect heat radiation.","use":["Keep the flask upright on a stable surface.","Pour a cold liquid in slowly, since the flask must cool down first.","Do not seal the lid tightly — the evaporating gas must be able to escape.","Do not knock the flask: if a glass wall breaks, the vacuum can make the pieces fly."],"inventor":"James Dewar (Scotland, UK)","year":"1892","history":"The Scottish scientist James Dewar created this vessel in 1892 to store cold liquids during his research on liquefying gases. He did not patent his invention. In 1904 the company Thermos was founded in Germany to make household vacuum flasks based on the same principle.","fact":"Using his flask, James Dewar became the first to liquefy hydrogen in 1898.","safety":"Wear safety goggles and insulated gloves with liquid nitrogen — it can freeze skin instantly."},"ru":{"name":"Сосуд Дьюара","short":"Сосуд Дьюара — сосуд с двойными стенками и вакуумом между ними, долго сохраняющий температуру содержимого.","purpose":"В лаборатории его используют для хранения и переноса очень холодных жидкостей, например жидкого азота. Вакуум почти полностью останавливает передачу тепла, поэтому жидкость испаряется медленно. Бытовой термос работает по тому же принципу.","material":"Изготавливается из двустенного стекла или нержавеющей стали. Воздух между стенками откачивают, а стеклянные стенки серебрят, чтобы отражать тепловое излучение.","use":["Держите сосуд вертикально на устойчивой поверхности.","Наливайте холодную жидкость медленно, так как сосуд сначала должен остыть.","Не закрывайте крышку герметично — испаряющийся газ должен выходить.","Не ударяйте сосуд: при разрушении стеклянной стенки из-за вакуума осколки могут разлететься."],"inventor":"Джеймс Дьюар (Шотландия, Великобритания)","year":"1892","history":"Шотландский учёный Джеймс Дьюар создал этот сосуд в 1892 году для хранения холодных жидкостей в своих исследованиях сжижения газов. Он не стал патентовать изобретение. В 1904 году в Германии была основана компания Thermos, выпускавшая бытовые термосы на том же принципе.","fact":"С помощью своего сосуда Джеймс Дьюар в 1898 году первым получил жидкий водород.","safety":"При работе с жидким азотом надевайте защитные очки и теплоизолирующие перчатки — он мгновенно обмораживает кожу."}},{"id":"soxhlet","icon":"🔄","cat":"apparatus","uz":{"name":"Soxlet apparati","short":"Soxlet apparati — qattiq moddadan kerakli tarkibiy qismni erituvchi yordamida qayta-qayta yuvib ajratib oladigan shisha qurilma.","purpose":"U o'simlik, oziq-ovqat yoki tuproqdan yog'lar, moylar va boshqa eriydigan moddalarni ajratib olish (ekstraksiya) uchun ishlatiladi. Erituvchi qaynab, sovutgichda kondensatsiyalanadi va namunani yuvadi, keyin sifon orqali kolbaga qaytadi. Shu tarzda oz miqdordagi erituvchi bilan ko'p marta ekstraksiya qilinadi.","material":"Issiqqa chidamli borosilikat shishadan yasaladi, chunki u qizdirish va harorat o'zgarishiga bardosh beradi hamda erituvchilarga chidamli. Namuna qog'oz yoki tsellyulozadan yasalgan gilzaga solinadi.","use":["Maydalangan namunani gilzaga solib, ekstraktorning o'rta qismiga joylashtiring.","Pastki kolbaga erituvchi quying va qurilmani kolba, ekstraktor va sovutgich tartibida yig'ing.","Sovutgichga suv yuboring, so'ngra kolbani suv hammomi yoki isitgichda asta qizdiring.","Bir necha sikldan keyin isitishni to'xtating va ajratilgan moddani kolbadan oling."],"inventor":"Frans fon Soxlet (Germaniya)","year":"1879","history":"Nemis agrokimyogari Frans fon Soxlet 1879-yilda bu apparatni asosan sut va oziq-ovqat mahsulotlaridagi yog' miqdorini aniqlash uchun ixtiro qilgan. U kam erituvchi sarflab, to'liq ekstraksiya qilish imkonini berdi. Bugungi kunda ham Soxlet usuli oziq-ovqat va farmatsevtika tahlilida standart usullardan biri hisoblanadi.","fact":"Soxlet apparatida bir xil erituvchi soatlab o'zi aylanib yuradi — bunda inson aralashuvi deyarli kerak bo'lmaydi.","safety":"Ko'p erituvchilar oson yonadi, shuning uchun ochiq alanga emas, suv hammomi yoki elektr isitgichdan foydalaning va ishni mo'rili shkafda bajaring."},"en":{"name":"Soxhlet extractor","short":"A Soxhlet extractor is a glass apparatus that removes a wanted component from a solid by washing it again and again with a solvent.","purpose":"It is used to extract fats, oils and other soluble substances from plants, foods or soil. The solvent boils, condenses in the condenser, washes the sample and then returns to the flask through a siphon. In this way a small amount of solvent extracts the sample many times.","material":"It is made of heat-resistant borosilicate glass, which withstands heating and temperature changes and resists solvents. The sample is placed in a thimble made of thick filter paper or cellulose.","use":["Put the ground sample into a thimble and place it in the middle part of the extractor.","Pour solvent into the bottom flask and assemble flask, extractor and condenser in that order.","Turn on the condenser water, then heat the flask gently on a water bath or heating mantle.","After several cycles, stop heating and collect the extracted substance from the flask."],"inventor":"Franz von Soxhlet (Germany)","year":"1879","history":"The German agricultural chemist Franz von Soxhlet invented this apparatus in 1879, mainly to determine the fat content of milk and food products. It allowed complete extraction while using little solvent. Today the Soxhlet method is still one of the standard methods in food and pharmaceutical analysis.","fact":"In a Soxhlet extractor the same solvent cycles by itself for hours with almost no human help.","safety":"Many solvents are highly flammable, so use a water bath or electric heater rather than an open flame, and work in a fume hood."},"ru":{"name":"Аппарат Сокслета","short":"Аппарат Сокслета — стеклянный прибор, извлекающий нужный компонент из твёрдого вещества многократной промывкой растворителем.","purpose":"Его используют для извлечения (экстракции) жиров, масел и других растворимых веществ из растений, продуктов питания или почвы. Растворитель кипит, конденсируется в холодильнике, промывает образец и через сифон возвращается в колбу. Так небольшое количество растворителя многократно экстрагирует образец.","material":"Изготавливается из термостойкого боросиликатного стекла, которое выдерживает нагрев и перепады температуры и устойчиво к растворителям. Образец помещают в гильзу из плотной фильтровальной бумаги или целлюлозы.","use":["Поместите измельчённый образец в гильзу и вставьте её в среднюю часть экстрактора.","Налейте растворитель в нижнюю колбу и соберите прибор в порядке: колба, экстрактор, холодильник.","Пустите воду в холодильник, затем осторожно нагревайте колбу на водяной бане или колбонагревателе.","После нескольких циклов прекратите нагрев и извлеките полученное вещество из колбы."],"inventor":"Франц фон Сокслет (Германия)","year":"1879","history":"Немецкий агрохимик Франц фон Сокслет изобрёл этот аппарат в 1879 году, главным образом для определения содержания жира в молоке и пищевых продуктах. Он позволил проводить полную экстракцию при малом расходе растворителя. И сегодня метод Сокслета остаётся одним из стандартных в пищевом и фармацевтическом анализе.","fact":"В аппарате Сокслета один и тот же растворитель часами циркулирует сам, почти без участия человека.","safety":"Многие растворители легко воспламеняются, поэтому используйте водяную баню или электронагреватель вместо открытого пламени и работайте в вытяжном шкафу."}},{"id":"spatula","icon":"🥄","cat":"support","uz":{"name":"Shpatel (qoshiqcha)","short":"Shpatel — kukun va qattiq moddalarni olish, ko'chirish va solish uchun ishlatiladigan kichik kurakcha yoki qoshiqcha.","purpose":"U idishdan oz miqdorda qattiq reaktiv olib, tarozi, probirka yoki kolbaga solish uchun xizmat qiladi. Moddalarni qo'l bilan ushlamaslik xavfsizlik va tozalik uchun muhim. Ba'zi shpatellar bilan cho'kmani qirib olish yoki aralashtirish ham mumkin.","material":"Zanglamaydigan po'lat, chinni, shisha yoki plastmassadan yasaladi. Zanglamaydigan po'lat ko'pchilik moddalar bilan reaksiyaga kirishmaydi va oson tozalanadi.","use":["Har bir reaktiv uchun toza va quruq shpatel ishlating.","Moddani kerakligidan ko'proq olmang.","Ortiqcha moddani reaktiv idishiga qaytarmang — u ifloslanishi mumkin.","Ishdan keyin shpatelni yuvib, quriting."],"inventor":"Noma'lum — qadimdan qo'llanadi","year":"Qadimgi davr","history":"Kichik kurakcha va qoshiqchalardan qadimdan tabiblar, dorishunoslar va alkimyogarlar dorilarni o'lchash va aralashtirish uchun foydalangan. Laboratoriya kimyosi rivojlanishi bilan ular turli shakl va materiallardan yasala boshladi. Hozir ikki uchli (bir uchi kurakcha, bir uchi qoshiqcha) shpatellar keng tarqalgan.","fact":"Shpatel so'zi lotincha spatula — kichik kurakcha so'zidan kelib chiqqan.","safety":"Reaktivlarni hech qachon qo'l bilan ushlamang va tatib ko'rmang — faqat toza shpateldan foydalaning."},"en":{"name":"Spatula (scoop)","short":"A spatula is a small blade or scoop used to take, move and add powders and solid substances.","purpose":"It is used to take a small amount of a solid reagent from a container and put it onto a balance or into a test tube or flask. Not touching chemicals with your hands is important for safety and cleanliness. Some spatulas can also scrape out a precipitate or stir a mixture.","material":"It is made of stainless steel, porcelain, glass or plastic. Stainless steel does not react with most substances and is easy to clean.","use":["Use a clean, dry spatula for each reagent.","Do not take more substance than you need.","Do not return excess substance to the reagent bottle — it may contaminate it.","Wash and dry the spatula after use."],"inventor":"Unknown — used since ancient times","year":"Ancient times","history":"Small blades and spoons have been used since antiquity by healers, pharmacists and alchemists to measure and mix medicines. As laboratory chemistry developed, they were made in many shapes and materials. Today double-ended spatulas, with a flat blade at one end and a scoop at the other, are common.","fact":"The word spatula comes from Latin, meaning a small flat blade.","safety":"Never touch or taste chemicals — always use a clean spatula."},"ru":{"name":"Шпатель (ложечка)","short":"Шпатель — небольшая лопаточка или ложечка для набора, переноса и насыпания порошков и твёрдых веществ.","purpose":"Им берут небольшое количество твёрдого реактива из банки и насыпают на весы, в пробирку или колбу. Не касаться веществ руками важно для безопасности и чистоты. Некоторыми шпателями можно также соскрести осадок или перемешать смесь.","material":"Изготавливается из нержавеющей стали, фарфора, стекла или пластмассы. Нержавеющая сталь не реагирует с большинством веществ и легко моется.","use":["Для каждого реактива используйте чистый и сухой шпатель.","Не берите вещества больше, чем нужно.","Не возвращайте излишек вещества в банку с реактивом — его можно загрязнить.","После работы вымойте и высушите шпатель."],"inventor":"Неизвестен — используется с древности","year":"Древность","history":"Маленькими лопаточками и ложечками с древности пользовались лекари, аптекари и алхимики, чтобы отмерять и смешивать лекарства. С развитием лабораторной химии их стали делать разной формы и из разных материалов. Сегодня распространены двусторонние шпатели: с одной стороны лопаточка, с другой — ложечка.","fact":"Слово «шпатель» происходит от латинского spatula — маленькая лопатка.","safety":"Никогда не трогайте реактивы руками и не пробуйте их на вкус — пользуйтесь только чистым шпателем."}},{"id":"balance","icon":"⚖️","cat":"measure","uz":{"name":"Laboratoriya tarozisi (analitik tarozi)","short":"Analitik tarozi — moddalar massasini juda aniq, odatda 0,0001 g gacha o'lchaydigan laboratoriya tarozisi.","purpose":"U reaktivlarni aniq tortib olish, eritmalar tayyorlash va miqdoriy tahlil uchun ishlatiladi. Aniq massani bilish orqali kimyoviy hisob-kitoblarni to'g'ri bajarish mumkin. Shamol va changdan himoya qilish uchun u shisha qutichaga joylashtirilgan.","material":"Zamonaviy analitik tarozilar elektron bo'lib, metall korpus va shisha himoya qutisidan iborat. Tortish kosachasi zanglamaydigan po'latdan yasaladi.","use":["Tarozini tekis, tebranmaydigan stolga qo'ying va sathini tekshiring.","Idish yoki tortish qog'ozini qo'yib, tarozini nolga keltiring (tara).","Moddani shpatel bilan asta qo'shing va eshikchalarni yopib, ko'rsatkich barqarorlashishini kuting.","Issiq idishni tortmang va tortish kosachasiga to'kilgan moddani darhol tozalang."],"inventor":"Noma'lum — tarozi qadimdan ma'lum; aniq analitik tarozi XVIII asrda rivojlangan","year":"Qadimgi davr; analitik tarozi — XVIII asr","history":"Shayinli tarozilar qadimgi Misr va Mesopotamiyada ishlatilgan. XVIII asrda kimyoda aniq tortish muhim bo'lib qoldi: analitik tarozining dastlabki ko'rinishi ko'pincha Jozef Blek bilan bog'lanadi, Antuan Lavuazye esa aniq tarozilar yordamida massaning saqlanish qonunini isbotlagan. XX asrda elektron analitik tarozilar paydo bo'ldi.","fact":"Analitik tarozi shunchalik sezgirki, barmoq izi yoki nafasdan qolgan namlik ham natijani o'zgartirishi mumkin.","safety":"Moddani to'g'ridan-to'g'ri tortish kosachasiga qo'ymang — har doim idish yoki tortish qog'ozidan foydalaning."},"en":{"name":"Laboratory balance (analytical balance)","short":"An analytical balance is a laboratory balance that measures the mass of substances very precisely, usually to 0.0001 g.","purpose":"It is used to weigh reagents accurately, to prepare solutions and for quantitative analysis. Knowing the exact mass makes correct chemical calculations possible. It sits inside a glass draft shield that protects it from air currents and dust.","material":"Modern analytical balances are electronic, with a metal body and a glass draft shield. The weighing pan is made of stainless steel.","use":["Place the balance on a flat, vibration-free bench and check that it is level.","Put on a container or weighing paper and zero the balance (tare).","Add the substance slowly with a spatula, close the doors and wait for a steady reading.","Do not weigh hot objects, and clean any spill on the pan at once."],"inventor":"Unknown — balances are ancient; the precise analytical balance developed in the 18th century","year":"Ancient times; analytical balance — 18th century","history":"Beam balances were used in ancient Egypt and Mesopotamia. In the 18th century accurate weighing became essential in chemistry: an early analytical balance is often credited to Joseph Black, and Antoine Lavoisier used precise balances to show the conservation of mass. Electronic analytical balances appeared in the 20th century.","fact":"An analytical balance is so sensitive that a fingerprint or moisture from your breath can change the result.","safety":"Never put a substance directly on the pan — always use a container or weighing paper."},"ru":{"name":"Лабораторные весы (аналитические весы)","short":"Аналитические весы — лабораторные весы, измеряющие массу веществ очень точно, обычно до 0,0001 г.","purpose":"Их используют для точного взвешивания реактивов, приготовления растворов и количественного анализа. Зная точную массу, можно правильно выполнять химические расчёты. Весы помещены в стеклянный шкафчик, защищающий от потоков воздуха и пыли.","material":"Современные аналитические весы электронные, с металлическим корпусом и стеклянным защитным шкафчиком. Чашка весов делается из нержавеющей стали.","use":["Установите весы на ровный стол без вибраций и проверьте уровень.","Поставьте ёмкость или бумагу для взвешивания и обнулите весы (тара).","Добавляйте вещество шпателем понемногу, закройте дверцы и дождитесь стабильного показания.","Не взвешивайте горячие предметы и сразу убирайте просыпанное на чашку вещество."],"inventor":"Неизвестен — весы известны с древности; точные аналитические весы развились в XVIII веке","year":"Древность; аналитические весы — XVIII век","history":"Рычажные весы применялись в Древнем Египте и Месопотамии. В XVIII веке точное взвешивание стало важным в химии: создание ранних аналитических весов часто приписывают Джозефу Блэку, а Антуан Лавуазье с помощью точных весов доказал сохранение массы. В XX веке появились электронные аналитические весы.","fact":"Аналитические весы настолько чувствительны, что отпечаток пальца или влага от дыхания могут изменить результат.","safety":"Никогда не кладите вещество прямо на чашку — всегда используйте ёмкость или бумагу для взвешивания."}},{"id":"hydrometer","icon":"📏","cat":"measure","uz":{"name":"Areometr","short":"Areometr — suyuqlikka botirib, uning zichligini o'lchaydigan, pastki qismi og'irlashtirilgan shisha suzgich.","purpose":"U eritmalar, kislotalar, spirt, sut yoki akkumulyator elektrolitining zichligini aniqlash uchun ishlatiladi. Zichlik bo'yicha eritmaning konsentratsiyasini ham bilish mumkin. Areometr suyuqlikka qanchalik chuqur botsa, suyuqlik zichligi shunchalik kichik bo'ladi.","material":"Shishadan yasaladi, pastki qismiga qo'rg'oshin donachalari yoki simob solinadi — shu tufayli u tik holda suzadi. Ingichka bo'yin qismida qog'oz shkala joylashgan.","use":["Suyuqlikni baland o'lchov silindriga quying.","Areometrni ehtiyotkorlik bilan botiring va qo'yib yuboring — u silindr devoriga tegmasin.","Areometr to'xtagach, suyuqlik sathi bo'yicha shkalani ko'z darajasida o'qing.","Ishdan keyin areometrni yuvib, quriting."],"inventor":"Noma'lum — eng qadimgi tavsifi Kirenalik Sinesiyning Gipatiyaga maktubida uchraydi","year":"Taxminan V asr boshlari","history":"Areometrning ma'lum bo'lgan eng qadimgi tavsifi Kirenalik Sinesiyning Iskandariyalik olima Gipatiyaga yozgan maktubida uchraydi (taxminan 400-yillar). Uning tamoyili Arximed qonuniga asoslanadi. 1768-yilda fransuz kimyogari Antuan Bome areometrlar uchun mashhur Bome shkalasini taklif qilgan.","fact":"Areometr Arximed qonuni asosida ishlaydi: suzayotgan jism o'z og'irligiga teng suyuqlikni siqib chiqaradi.","safety":"Areometrni silindrga tashlamang — uning pastki qismi og'ir va u silindr tubini sindirishi mumkin."},"en":{"name":"Hydrometer","short":"A hydrometer is a weighted glass float that is placed in a liquid to measure its density.","purpose":"It is used to find the density of solutions, acids, alcohol, milk or battery acid. From the density, the concentration of a solution can also be found. The deeper the hydrometer sinks, the lower the density of the liquid.","material":"It is made of glass, with lead shot or mercury in the bottom so that it floats upright. A paper scale sits inside the narrow stem.","use":["Pour the liquid into a tall measuring cylinder.","Lower the hydrometer gently and let go — it should not touch the cylinder wall.","When it stops moving, read the scale at the liquid surface with your eye at the same level.","Rinse and dry the hydrometer after use."],"inventor":"Unknown — the earliest description is in a letter from Synesius of Cyrene to Hypatia","year":"Around the early 5th century","history":"The earliest known description of a hydrometer is in a letter written by Synesius of Cyrene to the Alexandrian scholar Hypatia, around the year 400. Its principle is based on Archimedes' principle. In 1768 the French chemist Antoine Baumé proposed the well-known Baumé scale for hydrometers.","fact":"A hydrometer works by Archimedes' principle: a floating object pushes aside a weight of liquid equal to its own weight.","safety":"Do not drop the hydrometer into the cylinder — its heavy bottom can crack the base of the cylinder."},"ru":{"name":"Ареометр","short":"Ареометр — стеклянный поплавок с утяжелённым низом, который погружают в жидкость для измерения её плотности.","purpose":"Им определяют плотность растворов, кислот, спирта, молока или электролита аккумуляторов. По плотности можно узнать и концентрацию раствора. Чем глубже погружается ареометр, тем меньше плотность жидкости.","material":"Изготавливается из стекла, в нижнюю часть помещают свинцовую дробь или ртуть, поэтому он плавает вертикально. Бумажная шкала находится внутри узкой трубки.","use":["Налейте жидкость в высокий мерный цилиндр.","Осторожно опустите ареометр и отпустите — он не должен касаться стенок цилиндра.","Когда он остановится, снимите показание по уровню жидкости, держа глаза на этом уровне.","После работы промойте и высушите ареометр."],"inventor":"Неизвестен — самое раннее описание есть в письме Синезия Киренского к Гипатии","year":"Около начала V века","history":"Самое раннее известное описание ареометра содержится в письме Синезия Киренского к александрийской учёной Гипатии, около 400 года. Его принцип основан на законе Архимеда. В 1768 году французский химик Антуан Боме предложил известную шкалу Боме для ареометров.","fact":"Ареометр работает по закону Архимеда: плавающее тело вытесняет жидкость, вес которой равен его собственному весу.","safety":"Не бросайте ареометр в цилиндр — тяжёлый низ может разбить дно цилиндра."}},{"id":"wash_bottle","icon":"💧","cat":"glass","uz":{"name":"Yuvgich (promyvalka)","short":"Yuvgich — siqilganda ingichka nay orqali suv yoki erituvchini oqim bilan chiqaradigan idish.","purpose":"U asboblarni distillangan suv bilan chayish, cho'kmani filtrga yuvib tushirish va idishdagi qoldiqlarni yig'ish uchun ishlatiladi. Ingichka oqim suyuqlikni aniq kerakli joyga yo'naltirish imkonini beradi. Ba'zi yuvgichlar spirt yoki aseton kabi erituvchilar uchun mo'ljallangan.","material":"Hozir ko'pincha egiluvchan polietilendan yasaladi — uni qo'l bilan siqish oson va u sinmaydi. Ilgari shisha kolba va nayli tiqindan yig'ilgan bo'lib, havo puflab ishlatilgan.","use":["Yuvgichga faqat yorlig'ida ko'rsatilgan suyuqlikni quying.","Nayni kerakli joyga yo'naltirib, idishni asta siqing.","Cho'kmani yuvishda oqimni idish devori bo'ylab yo'naltiring.","Nay uchi iflos sirtlarga tegmasin."],"inventor":"Noma'lum — asta-sekin rivojlangan","year":"XIX asr (shisha), XX asr (plastik)","history":"XIX asrda yuvgich shisha kolba va ikki nayli tiqindan yasalgan: bir nayga puflanganda, ikkinchisidan suv oqimi chiqqan. XX asrning o'rtalarida polietilen keng tarqalgach, qo'lda siqiladigan plastik yuvgichlar paydo bo'ldi. Ular qulayroq va xavfsizroq bo'lgani uchun shisha yuvgichlarni deyarli siqib chiqardi.","fact":"Laboratoriyalarda yuvgichlar ko'pincha rangli qopqoq yoki yorliq bilan belgilanadi, shunda suv va erituvchilar adashtirilmaydi.","safety":"Yonuvchi erituvchili yuvgichni alangadan uzoq tuting va yuvgichga yorlig'ida yozilmagan suyuqlikni quymang."},"en":{"name":"Wash bottle","short":"A wash bottle is a squeeze bottle that sends out a thin stream of water or solvent through a nozzle.","purpose":"It is used to rinse equipment with distilled water, to wash a precipitate onto a filter and to collect the last traces from a vessel. The thin stream lets you aim the liquid exactly where it is needed. Some wash bottles are meant for solvents such as ethanol or acetone.","material":"Today it is usually made of flexible polyethylene, which is easy to squeeze and does not break. In the past it was assembled from a glass flask and a stopper with tubes and worked by blowing.","use":["Fill the wash bottle only with the liquid shown on its label.","Point the nozzle where needed and squeeze the bottle gently.","When washing a precipitate, direct the stream along the wall of the vessel.","Do not let the nozzle tip touch dirty surfaces."],"inventor":"Unknown — developed gradually","year":"19th century (glass), 20th century (plastic)","history":"In the 19th century a wash bottle was made from a glass flask and a stopper with two tubes: blowing into one tube pushed a stream of water out of the other. In the mid-20th century, when polyethylene became widespread, squeezable plastic wash bottles appeared. Being handier and safer, they almost completely replaced the glass ones.","fact":"Laboratories often mark wash bottles with coloured caps or labels so that water and solvents are not mixed up.","safety":"Keep wash bottles with flammable solvents away from flames, and never fill one with a liquid other than the one on its label."},"ru":{"name":"Промывалка","short":"Промывалка — сжимаемая ёмкость, которая выпускает тонкую струю воды или растворителя через носик.","purpose":"Её используют для ополаскивания посуды дистиллированной водой, смывания осадка на фильтр и сбора остатков из сосуда. Тонкая струя позволяет направить жидкость точно туда, куда нужно. Некоторые промывалки предназначены для растворителей, например этанола или ацетона.","material":"Сейчас её обычно делают из гибкого полиэтилена — его легко сжимать, и он не бьётся. Раньше её собирали из стеклянной колбы и пробки с трубками и работали, вдувая воздух.","use":["Наливайте в промывалку только жидкость, указанную на этикетке.","Направьте носик в нужное место и аккуратно сожмите ёмкость.","При промывании осадка направляйте струю по стенке сосуда.","Не допускайте, чтобы кончик носика касался грязных поверхностей."],"inventor":"Неизвестен — прибор развивался постепенно","year":"XIX век (стеклянная), XX век (пластиковая)","history":"В XIX веке промывалку делали из стеклянной колбы и пробки с двумя трубками: при вдувании воздуха в одну трубку из другой вытекала струя воды. В середине XX века, с распространением полиэтилена, появились пластиковые промывалки, которые сжимают рукой. Будучи удобнее и безопаснее, они почти полностью вытеснили стеклянные.","fact":"В лабораториях промывалки часто отмечают цветными крышками или этикетками, чтобы не перепутать воду и растворители.","safety":"Держите промывалки с горючими растворителями подальше от огня и не наливайте в них жидкость, не указанную на этикетке."}}];
